-- Generated by packages/database-src/supabase-dump-for-full-version.ts from a
-- database at fsm_core 1.2.0; do not edit.
-- The fsm_* roles (--role-only dump) and the fsm_core schema (--schema
-- dump), plus the pgmq grants (access-control schema file) and the pg_cron job.

-- ── Roles (from `supabase db dump --role-only`, fsm_* only) ────────────────
DO $roles$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'fsm_admin') THEN
    CREATE ROLE "fsm_admin" WITH INHERIT NOCREATEROLE NOCREATEDB NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'fsm_authenticator') THEN
    CREATE ROLE "fsm_authenticator" WITH NOINHERIT NOCREATEROLE NOCREATEDB LOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'fsm_operator') THEN
    CREATE ROLE "fsm_operator" WITH INHERIT NOCREATEROLE NOCREATEDB NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'fsm_sim') THEN
    CREATE ROLE "fsm_sim" WITH INHERIT NOCREATEROLE NOCREATEDB NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'fsm_worker') THEN
    CREATE ROLE "fsm_worker" WITH INHERIT NOCREATEROLE NOCREATEDB NOLOGIN;
  END IF;
END;
$roles$;

GRANT "fsm_operator" TO "fsm_admin";
GRANT "fsm_operator" TO "fsm_authenticator";

-- The installing login gets the memberships the dumped database's owner has
-- (by name: on Supabase, GRANT … TO CURRENT_USER segfaults the backend).
DO $owner$
BEGIN
  EXECUTE format('GRANT "fsm_admin", "fsm_authenticator", "fsm_operator", "fsm_worker" TO %I', current_user);
END;
$owner$;


