--
-- Name: archive_event_from_fsm_type_worker_v2("text", bigint, "jsonb", "jsonb", "jsonb", "jsonb", "jsonb", "jsonb", "jsonb", "jsonb", "jsonb", "jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."archive_event_from_fsm_type_worker_v2"("remove_from_current_fsm_instance_queue_id" "text", "remove_current_queue_msg_id" bigint, "to_be_removed_schedule_queue_msg_ids" "jsonb", "to_be_removed_async_operation_queue_msg_ids" "jsonb", "to_be_added_schedule_queue_data" "jsonb", "to_be_added_async_operation_queue_data" "jsonb", "input_total_schedule_queue_data" "jsonb", "input_total_async_operation_queue_data" "jsonb", "fsm_instance_data_save_fsm_status" "jsonb", "fsm_instance_data_save_fsm_state" "jsonb", "fsm_instance_data_save_fsm_context" "jsonb", "fsm_instance_data_save_fsm_xstate_state" "jsonb", "raised_events" "jsonb" DEFAULT '[]'::"jsonb", "processed_internal_event" "jsonb" DEFAULT NULL::"jsonb", "fsm_instance_data_save_fsm_error" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    i int;

    instance_row fsm_core.fsm_instance%ROWTYPE;
    current_total_schedule_queue_data jsonb;
    current_total_async_operation_queue_data jsonb;

    schedule_queue_entry jsonb;
    remove_schedule boolean;
    schedule_queue_message jsonb;
    confirmed_removed_schedule_queue_data jsonb[] := '{}';
    confirmed_match_for_schedule boolean;
    not_confirmed_removed_schedule_queue_data jsonb[] := '{}';

    async_operation_queue_entry jsonb;
    remove_async_operation boolean;
    async_operation_queue_message jsonb;
    confirmed_removed_async_operation_queue_data jsonb[] := '{}';
    confirmed_match_for_async_operation boolean;
    not_confirmed_removed_async_operation_queue_data jsonb[] := '{}';
    stop_result jsonb;

    to_be_added_schedule_queue_data_entry jsonb;
    to_be_added_schedule_queue_data_entry_delay int;
    output_schedule_result jsonb;

    to_be_added_async_operation_queue_data_entry jsonb;
    output_async_operation_result jsonb;

    new_total_schedule_queue_data jsonb := '[]'::jsonb;
    new_total_async_operation_queue_data jsonb := '[]'::jsonb;

    confirmed_removed_schedule_queue_data_success jsonb[] := '{}';
    confirmed_removed_schedule_queue_data_failed jsonb[] := '{}';

    confirmed_removed_async_operation_queue_data_success jsonb[] := '{}';
    confirmed_removed_async_operation_queue_data_failed jsonb[] := '{}';

    added_schedule_queue_data jsonb[] := '{}';
    added_async_operation_queue_data jsonb[] := '{}';

    terminal_stopped_async_operation_queue_data jsonb := '[]'::jsonb;
    terminal_archived_msg_ids bigint[] := '{}';

    parent_notify_result jsonb;
    child_parent_fsm_name text;
    child_parent_fsm_version text;

    -- SPEC-010's cycle cap: internal events in a row before the instance is
    -- set to error, so a cycle (an onDone that enters another final state that
    -- leads back) can't run forever.
    max_internal_events CONSTANT integer := 100;
    new_internal_event_queue jsonb;
    new_internal_event_count integer;
    saved_status jsonb;
    saved_error jsonb;
    final_status text;
    raised_event jsonb;
    processed_message jsonb;
    processed_event_type text;
    processed_event_source jsonb;
BEGIN
    -- 1. Lock the instance first: every decision below is made on locked
    --    state, serialised with a stop (stop_fsm_instance_v2) and with a
    --    second fsmlet processing the same message.
    SELECT * INTO instance_row
    FROM fsm_core.fsm_instance fi
    WHERE fi.id = remove_from_current_fsm_instance_queue_id::uuid
    FOR NO KEY UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'archive_event_from_fsm_type_worker_v2: fsm instance % not found', remove_from_current_fsm_instance_queue_id;
    END IF;

    -- 2. Status gate. A stopped or finished instance takes no more macrosteps,
    --    as XState drops events sent to an actor that isn't active. Typically a
    --    parent stopped this child (stop_child_fsm_v2) while its fsmlet was
    --    computing a macrostep, or the fsmlet is reading the xstate.stop message
    --    that stop sends to wake it. The processed message is archived, whatever
    --    archive returns (the stop may have archived it already), so it isn't
    --    delivered again; an internal event has nothing to archive. Checked
    --    before the internal-queue head below: a stop clears that queue, and the
    --    reason is that the instance stopped. (A new instance has no status yet:
    --    it is active.)
    IF COALESCE(instance_row.fsm_instance_status #>> '{}', 'active') <> 'active' THEN
        IF remove_current_queue_msg_id IS NOT NULL THEN
            PERFORM pgmq.archive(queue_name := remove_from_current_fsm_instance_queue_id, msg_id := remove_current_queue_msg_id);
        END IF;
        RETURN fsm_core.discard_fsm_macrostep_v2(
            instance_row, 'instance_not_active', remove_current_queue_msg_id, processed_internal_event
        );
    END IF;

    -- 3. Consume the processed event, gated, so each one is applied once. Two
    --    fsmlets can hold the same event: one whose visibility timeout ran out
    --    or that crashed, and the one that took the instance after it. Step 1's
    --    lock makes their saves run one after the other; this decides that only
    --    the first counts.
    IF processed_internal_event IS NOT NULL THEN
        -- An internal event: it must still be the head of the queue, as the
        -- worker took it. Anything else means another fsmlet already processed
        -- and removed it. The worker passes the event back exactly as it read
        -- it, internalEventId included (step 9), so this compares identity:
        -- with two identical events in a row, a late save for the first can't
        -- match the second (#546). An event queued before #546 has no id and
        -- is compared by its contents.
        new_internal_event_queue := COALESCE(instance_row.internal_event_queue, '[]'::jsonb);
        IF new_internal_event_queue->0 IS DISTINCT FROM processed_internal_event THEN
            RETURN fsm_core.discard_fsm_macrostep_v2(
                instance_row, 'internal_event_not_head', NULL, processed_internal_event
            );
        END IF;
        new_internal_event_queue := new_internal_event_queue - 0;
        new_internal_event_count := COALESCE(instance_row.internal_event_count, 0) + 1;
    ELSE
        -- A pgmq message: archiving it is the gate, as pgmq.archive deletes the
        -- message row and only one transaction can. False: it was already
        -- archived, either by another fsmlet that got it after its visibility
        -- timeout and saved first, or by a stop (stop_fsm_instance_v2 archives
        -- the whole queue). No message id (a direct SQL call): not gated.
        -- The message is read first, for step 4: archiving moves it out of
        -- the queue table.
        IF remove_current_queue_msg_id IS NOT NULL THEN
            EXECUTE format('SELECT message FROM pgmq.%I WHERE msg_id = $1', 'q_' || remove_from_current_fsm_instance_queue_id)
            INTO processed_message
            USING remove_current_queue_msg_id;
            IF NOT pgmq.archive(queue_name := remove_from_current_fsm_instance_queue_id, msg_id := remove_current_queue_msg_id) THEN
                RETURN fsm_core.discard_fsm_macrostep_v2(
                    instance_row, 'message_already_archived', remove_current_queue_msg_id, NULL
                );
            END IF;
        END IF;
        new_internal_event_queue := COALESCE(instance_row.internal_event_queue, '[]'::jsonb);
        -- An event from the pgmq queue starts a new count.
        new_internal_event_count := 0;
    END IF;

    -- 4. Stale done/error actor events (SPEC-011 (c), #535). Re-entering a
    --    state starts a new invoke under the same invoke id, and the parent
    --    matches xstate.done.actor.<id> / xstate.error.actor.<id> by name. A
    --    result of the earlier invoke, queued before the parent's exit
    --    committed or after it, would be taken for the new invoke's. So the
    --    event's source (set by finish_async_operation_event_v2 for an actor,
    --    and by step 11 for a child FSM) must still be an invoke this instance
    --    holds: an entry of its totals with the same invoke_id and queue_id
    --    (and queue_msg_id, for an actor). Otherwise the macrostep is
    --    discarded, the same as XState ignoring the event. Checked here, under
    --    the instance's lock, not in the fsmlet: its copy of the totals is
    --    read without the lock. A message without a source (sent before
    --    #533/#535, or by the API) is processed as before.
    processed_event_type := processed_message->'eventData'->>'eventType';
    processed_event_source := processed_message->'source';
    IF processed_event_source IS NOT NULL
        AND (starts_with(processed_event_type, 'xstate.done.actor.')
             OR starts_with(processed_event_type, 'xstate.error.actor.'))
        AND NOT EXISTS (
            SELECT 1
            FROM jsonb_array_elements(COALESCE(instance_row.total_async_operation_queue_data, '[]'::jsonb)) held
            WHERE held.value->>'invoke_id' = processed_event_source->>'invoke_id'
              AND held.value->>'queue_id' = processed_event_source->>'queue_id'
              AND (NOT processed_event_source ? 'queue_msg_id'
                   OR (held.value->>'queue_msg_id')::bigint = (processed_event_source->>'queue_msg_id')::bigint)
        )
    THEN
        RETURN fsm_core.discard_fsm_macrostep_v2(
            instance_row, 'stale_actor_event', remove_current_queue_msg_id, NULL, processed_message
        );
    END IF;

    -- 5. The exit side, from the row's totals. The worker's copy was read
    --    without the lock; a difference is only reported.
    current_total_schedule_queue_data := COALESCE(instance_row.total_schedule_queue_data, '[]'::jsonb);
    current_total_async_operation_queue_data := COALESCE(instance_row.total_async_operation_queue_data, '[]'::jsonb);
    IF (input_total_schedule_queue_data IS NOT NULL
            AND input_total_schedule_queue_data IS DISTINCT FROM current_total_schedule_queue_data)
        OR (input_total_async_operation_queue_data IS NOT NULL
            AND input_total_async_operation_queue_data IS DISTINCT FROM current_total_async_operation_queue_data)
    THEN
        RAISE WARNING 'archive_event_from_fsm_type_worker_v2: the worker''s totals for instance % differ from the row; using the row', remove_from_current_fsm_instance_queue_id;
    END IF;

    -- 5a. Remove the cancelled scheduled events from the totals.
    -- A = current_total_schedule_queue_data
    -- B = to_be_removed_schedule_queue_msg_ids
    -- C = confirmed_removed_schedule_queue_data (cancelled)  ( C = A intersect B )
    -- D = not_confirmed_removed_schedule_queue_data (returned) ( D = B - C )
    FOR schedule_queue_entry IN
        SELECT value FROM jsonb_array_elements(current_total_schedule_queue_data) value
    LOOP
        remove_schedule := false;
        -- The scheduled event being processed now has fired: drop its entry
        -- (its message was archived in step 3, #516).
        CONTINUE WHEN (schedule_queue_entry->'queue_data'->>'queueMsgId')::bigint = remove_current_queue_msg_id;
        IF to_be_removed_schedule_queue_msg_ids IS NOT NULL THEN
            FOR i IN 0 .. jsonb_array_length(to_be_removed_schedule_queue_msg_ids)-1 LOOP
                schedule_queue_message := to_be_removed_schedule_queue_msg_ids->i;

                -- A cancel names the scheduled event (`id`, e.g.
                -- xstate.after.1000.<state id>); an entry is what
                -- send_event_to_fsm_queue_with_event_logs_v2 returned when it was
                -- scheduled (#516).
                IF (
                    (schedule_queue_entry->'queue_data'->'eventData'->>'eventType')::text = (schedule_queue_message->>'id')::text
                ) THEN
                    remove_schedule := true;

                    EXIT;
                END IF;
            END LOOP;
        END IF;

        IF remove_schedule THEN
            confirmed_removed_schedule_queue_data := array_append(confirmed_removed_schedule_queue_data, schedule_queue_entry);
        ELSE
            -- jsonb, not a SQL array: append with || (#495).
            new_total_schedule_queue_data := new_total_schedule_queue_data || jsonb_build_array(schedule_queue_entry);
        END IF;
    END LOOP;

    IF to_be_removed_schedule_queue_msg_ids IS NOT NULL THEN
        FOR i IN 0 .. jsonb_array_length(to_be_removed_schedule_queue_msg_ids)-1 LOOP
            schedule_queue_message := to_be_removed_schedule_queue_msg_ids->i;
            confirmed_match_for_schedule := false;
            FOREACH schedule_queue_entry IN ARRAY confirmed_removed_schedule_queue_data LOOP
                IF (
                    (schedule_queue_entry->'queue_data'->'eventData'->>'eventType')::text = (schedule_queue_message->>'id')::text
                ) THEN
                    confirmed_match_for_schedule := true;
                    EXIT;
                END IF;
            END LOOP;

            IF NOT confirmed_match_for_schedule THEN
                not_confirmed_removed_schedule_queue_data := array_append(not_confirmed_removed_schedule_queue_data, schedule_queue_message);
            END IF;
        END LOOP;
    END IF;

    -- Archive the cancelled schedules' messages. False: it was no longer
    -- there to cancel.
    FOREACH schedule_queue_entry IN ARRAY confirmed_removed_schedule_queue_data LOOP
        IF pgmq.archive(
            queue_name := remove_from_current_fsm_instance_queue_id,
            msg_id := (schedule_queue_entry->'queue_data'->>'queueMsgId')::bigint
        ) THEN
            confirmed_removed_schedule_queue_data_success := array_append(confirmed_removed_schedule_queue_data_success, schedule_queue_entry);
        ELSE
            confirmed_removed_schedule_queue_data_failed := array_append(confirmed_removed_schedule_queue_data_failed, schedule_queue_entry);
        END IF;
    END LOOP;

    -- 5b. Remove the stopped invokes from the totals, found by invoke_id and
    --     src (an entry from start_invoked_async_operation_v2, #526).
    FOR async_operation_queue_entry IN
        SELECT value FROM jsonb_array_elements(current_total_async_operation_queue_data) value
    LOOP
        remove_async_operation := false;
        IF to_be_removed_async_operation_queue_msg_ids IS NOT NULL THEN
            FOR i IN 0 .. jsonb_array_length(to_be_removed_async_operation_queue_msg_ids)-1 LOOP
                async_operation_queue_message := to_be_removed_async_operation_queue_msg_ids->i;

                IF (
                    async_operation_queue_entry->>'invoke_id' = async_operation_queue_message->>'id'
                    AND async_operation_queue_entry->>'src' = async_operation_queue_message->>'src'
                ) THEN
                    remove_async_operation := true;

                    EXIT;
                END IF;
            END LOOP;
        END IF;

        IF remove_async_operation THEN
            confirmed_removed_async_operation_queue_data := array_append(confirmed_removed_async_operation_queue_data, async_operation_queue_entry);
        ELSE
            new_total_async_operation_queue_data := new_total_async_operation_queue_data || jsonb_build_array(async_operation_queue_entry);
        END IF;
    END LOOP;

    IF to_be_removed_async_operation_queue_msg_ids IS NOT NULL THEN
        FOR i IN 0 .. jsonb_array_length(to_be_removed_async_operation_queue_msg_ids)-1 LOOP
            async_operation_queue_message := to_be_removed_async_operation_queue_msg_ids->i;
            confirmed_match_for_async_operation := false;
            FOREACH async_operation_queue_entry IN ARRAY confirmed_removed_async_operation_queue_data LOOP
                IF (
                    async_operation_queue_entry->>'invoke_id' = async_operation_queue_message->>'id'
                    AND async_operation_queue_entry->>'src' = async_operation_queue_message->>'src'
                ) THEN
                    confirmed_match_for_async_operation := true;
                    EXIT;
                END IF;
            END LOOP;

            IF NOT confirmed_match_for_async_operation THEN
                not_confirmed_removed_async_operation_queue_data := array_append(not_confirmed_removed_async_operation_queue_data, async_operation_queue_message);
            END IF;
        END LOOP;
    END IF;

    -- Stop them: an actor's queued message is cancelled, a child machine is
    -- stopped with its subtree. Failed: there was nothing left to stop (the
    -- message was already archived, or the child had already finished).
    FOREACH async_operation_queue_entry IN ARRAY confirmed_removed_async_operation_queue_data LOOP
        stop_result := fsm_core.stop_invoked_async_operation_v2(async_operation_queue_entry);
        IF COALESCE((stop_result->>'archive_result')::boolean, false) OR stop_result->>'status' = 'stopped' THEN
            confirmed_removed_async_operation_queue_data_success := array_append(confirmed_removed_async_operation_queue_data_success, async_operation_queue_entry);
        ELSE
            confirmed_removed_async_operation_queue_data_failed := array_append(confirmed_removed_async_operation_queue_data_failed, async_operation_queue_entry);
        END IF;
    END LOOP;

    -- 6. The final status, decided before anything is started: the worker's,
    --    unless the internal-event cycle cap is passed.
    saved_status := fsm_instance_data_save_fsm_status;
    IF new_internal_event_count > max_internal_events THEN
        saved_status := '"error"'::jsonb;
        saved_error := jsonb_build_object(
            'message', format('Infinite loop: more than %s internal events in a row (last: %s)',
                max_internal_events, processed_internal_event->>'eventType')
        );
    END IF;
    final_status := COALESCE(saved_status #>> '{}', 'active');

    -- 7. The entry side, only while active: a finished machine starts nothing.
    IF final_status = 'active' THEN
        -- 7a. Schedule the new delayed events.
        IF to_be_added_schedule_queue_data IS NOT NULL THEN
            FOR i IN 0 .. jsonb_array_length(to_be_added_schedule_queue_data)-1 LOOP
                to_be_added_schedule_queue_data_entry := to_be_added_schedule_queue_data->i;
                to_be_added_schedule_queue_data_entry_delay := COALESCE((to_be_added_schedule_queue_data_entry->>'delay')::integer, 0) / 1000;
                output_schedule_result := fsm_core.send_event_to_fsm_queue_with_event_logs_v2(
                    input_fsm_instance_id := remove_from_current_fsm_instance_queue_id::uuid,
                    input_fsm_instance_id_fsm_type := to_be_added_schedule_queue_data_entry->>'fsmType',
                    input_fsm_instance_id_fsm_version := to_be_added_schedule_queue_data_entry->>'fsmVersion',
                    input_event_name := to_be_added_schedule_queue_data_entry->>'id',
                    input_event_action_type := to_be_added_schedule_queue_data_entry->>'action_type',
                    input_event_data := to_be_added_schedule_queue_data_entry->'input',
                    input_event_delay := to_be_added_schedule_queue_data_entry_delay,
                    input_event_status := 'ACTIVE',
                    input_event_output := '{}'::jsonb,
                    input_error_message := NULL
                );
                added_schedule_queue_data := array_append(added_schedule_queue_data, output_schedule_result);
                new_total_schedule_queue_data := new_total_schedule_queue_data || output_schedule_result;
            END LOOP;
        END IF;

        -- 7b. Start the invokes of the states entered, as XState's spawnChild
        --     does (#526); each entry is kept until its invoking state exits.
        IF to_be_added_async_operation_queue_data IS NOT NULL THEN
            FOR i IN 0 .. jsonb_array_length(to_be_added_async_operation_queue_data)-1 LOOP
                to_be_added_async_operation_queue_data_entry := to_be_added_async_operation_queue_data->i;
                output_async_operation_result := fsm_core.start_invoked_async_operation_v2(
                    invoke_id := to_be_added_async_operation_queue_data_entry->>'id',
                    src := to_be_added_async_operation_queue_data_entry->>'src',
                    input := to_be_added_async_operation_queue_data_entry->'input',
                    action_type := to_be_added_async_operation_queue_data_entry->>'action_type',
                    async_operation_type := to_be_added_async_operation_queue_data_entry->>'asyncOperationType',
                    async_operation_version := to_be_added_async_operation_queue_data_entry->>'asyncOperationVersion',
                    async_operation_language := to_be_added_async_operation_queue_data_entry->>'asyncOperationLanguage',
                    parent_fsm_instance_id := remove_from_current_fsm_instance_queue_id::uuid,
                    parent_fsm_name := to_be_added_async_operation_queue_data_entry->>'parentFsmName',
                    parent_fsm_version := to_be_added_async_operation_queue_data_entry->>'parentFsmVersion'
                );
                added_async_operation_queue_data := array_append(added_async_operation_queue_data, output_async_operation_result);
                new_total_async_operation_queue_data := new_total_async_operation_queue_data || jsonb_build_array(output_async_operation_result);
            END LOOP;
        END IF;
    ELSE
        -- 8. Done, error or stopped: as XState stops an actor's children when
        --    it finishes or fails, every invoke still running is stopped, and
        --    every message left on the queue (delayed events included) is
        --    archived; nothing more is processed.
        FOR async_operation_queue_entry IN
            SELECT value FROM jsonb_array_elements(new_total_async_operation_queue_data) value
        LOOP
            terminal_stopped_async_operation_queue_data := terminal_stopped_async_operation_queue_data
                || jsonb_build_array(fsm_core.stop_invoked_async_operation_v2(async_operation_queue_entry));
        END LOOP;
        terminal_archived_msg_ids := fsm_core.archive_fsm_instance_queue_messages_v2(remove_from_current_fsm_instance_queue_id::uuid);
        new_total_async_operation_queue_data := '[]'::jsonb;
        new_total_schedule_queue_data := '[]'::jsonb;
    END IF;

    -- 9. The internal event queue (SPEC-010, #519).
    IF final_status = 'active' THEN
        -- internalQueue.push(...): this microstep's raised events go after the
        -- ones already waiting, each logged as an internal event. Each gets an
        -- internalEventId, its identity for step 3's gate (#546); the fsmlet
        -- doesn't pass it on to XState.
        FOR raised_event IN SELECT value FROM jsonb_array_elements(COALESCE(raised_events, '[]'::jsonb)) value
        LOOP
            raised_event := raised_event || jsonb_build_object('internalEventId', gen_random_uuid());
            new_internal_event_queue := new_internal_event_queue || jsonb_build_array(raised_event);
            INSERT INTO fsm_core.fsm_instance_queue_event_logs (
                fsm_instance_id, fsm_instance_id_fsm_type, fsm_instance_id_fsm_version,
                event_name, event_data, event_delay, event_source, event_status, event_output
            ) VALUES (
                instance_row.id, instance_row.fsm_type, instance_row.fsm_version,
                raised_event->>'eventType', raised_event, 0, 'internal', 'ACTIVE', '{}'::jsonb
            );
        END LOOP;
    ELSE
        -- Like XState's macrostep, which only runs while the snapshot is
        -- active.
        new_internal_event_queue := '[]'::jsonb;
    END IF;

    -- 10. Save the instance: its new totals, status, state, context, XState
    --     snapshot and internal event queue.
    UPDATE fsm_core.fsm_instance
    SET
        total_schedule_queue_data = new_total_schedule_queue_data,
        total_async_operation_queue_data = new_total_async_operation_queue_data,
        internal_event_queue = new_internal_event_queue,
        internal_event_count = new_internal_event_count,
        fsm_instance_error = COALESCE(saved_error, fsm_instance_data_save_fsm_error, fsm_instance_error),
        fsm_instance_status = saved_status,
        fsm_instance_state = fsm_instance_data_save_fsm_state,
        fsm_instance_context = fsm_instance_data_save_fsm_context,
        fsm_instance_xstate_state = fsm_instance_data_save_fsm_xstate_state
    WHERE id = instance_row.id;

    -- 11. If this instance was invoked by a parent FSM and has finished, tell
    --     the parent, as XState does for a child actor (#523):
    --     xstate.done.actor.<invoke id> when done, xstate.error.actor.<invoke
    --     id> on error, nothing when stopped (step 2 returned already). The
    --     payload is what XState puts on those events: the error on error
    --     (event.error), the one step 10 saved as this instance's error,
    --     which the parent saves as its own if no transition takes the event
    --     (#520); on done, the context, as fsm.json has no output yet (#532:
    --     the error event used to carry the context too). The parent row is
    --     only read, never locked: the event-log insert takes FOR KEY SHARE on
    --     it, which doesn't conflict with the parent's own FOR NO KEY UPDATE.
    IF instance_row.parent_fsm_instance_id IS NOT NULL
        AND final_status IN ('done', 'completed', 'final', 'error')
    THEN
        SELECT p.fsm_name, p.fsm_version
        INTO child_parent_fsm_name, child_parent_fsm_version
        FROM fsm_core.fsm_instance p
        WHERE p.id = instance_row.parent_fsm_instance_id;

        parent_notify_result := fsm_core.send_event_to_fsm_queue_with_event_logs_v2(
            input_fsm_instance_id              := instance_row.parent_fsm_instance_id,
            input_fsm_instance_id_fsm_type     := child_parent_fsm_name,
            input_fsm_instance_id_fsm_version  := child_parent_fsm_version,
            input_event_name                   := CASE
                                                      WHEN final_status = 'error'
                                                      THEN 'xstate.error.actor.'
                                                      ELSE 'xstate.done.actor.'
                                                  END || instance_row.parent_invoke_id,
            input_event_action_type            := 'childFsm_completed',
            input_event_data                   := CASE
                                                      WHEN final_status = 'error'
                                                      THEN COALESCE(saved_error, fsm_instance_data_save_fsm_error, instance_row.fsm_instance_error)
                                                      ELSE fsm_instance_data_save_fsm_context
                                                  END,
            input_event_delay                  := 0,
            input_event_status                 := 'ACTIVE',
            input_event_output                 := '{}'::jsonb,
            input_error_message                := CASE
                                                      WHEN final_status = 'error'
                                                      THEN COALESCE(saved_error, fsm_instance_data_save_fsm_error, instance_row.fsm_instance_error)->>'message'
                                                  END,
            -- This child, as the parent's entry for it names it, for the
            -- parent's stale-event check (step 4, #535).
            input_event_source                 := jsonb_build_object(
                                                      'invoke_id', instance_row.parent_invoke_id,
                                                      'queue_id', instance_row.id::text
                                                  )
        );
    END IF;

    -- 12. Return.
    RETURN jsonb_build_object(
         'discarded', false,
         'fsm_instance_status', saved_status,

         'confirmed_removed_schedule_queue_data_success', confirmed_removed_schedule_queue_data_success,
         'confirmed_removed_async_operation_queue_data_success', confirmed_removed_async_operation_queue_data_success,

         'confirmed_removed_schedule_queue_data_failed', confirmed_removed_schedule_queue_data_failed,
         'confirmed_removed_async_operation_queue_data_failed', confirmed_removed_async_operation_queue_data_failed,

         'not_confirmed_removed_schedule_queue_data', not_confirmed_removed_schedule_queue_data,
         'not_confirmed_removed_async_operation_queue_data', not_confirmed_removed_async_operation_queue_data,

         'added_schedule_queue_data', added_schedule_queue_data,
         'added_async_operation_queue_data', added_async_operation_queue_data,

         'new_total_schedule_queue_data', new_total_schedule_queue_data,
         'new_total_async_operation_queue_data', new_total_async_operation_queue_data,

         'old_total_schedule_queue_data', current_total_schedule_queue_data,
         'old_total_async_operation_queue_data', current_total_async_operation_queue_data,

         'terminal_stopped_async_operation_queue_data', terminal_stopped_async_operation_queue_data,
         'terminal_archived_msg_ids', to_jsonb(terminal_archived_msg_ids),

         'internal_event_queue', new_internal_event_queue,
         'internal_event_count', new_internal_event_count,
         'parent_notify_result', parent_notify_result
      );

END;
$_$;



--
-- Name: archive_fsm_instance_queue_messages_v2("uuid"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."archive_fsm_instance_queue_messages_v2"("input_fsm_instance_id" "uuid") RETURNS bigint[]
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    instance_queue_name text := input_fsm_instance_id::text;
    queued_msg_ids bigint[];
    archived_msg_ids bigint[] := '{}';
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pgmq.list_queues() q WHERE q.queue_name = instance_queue_name) THEN
        RETURN archived_msg_ids;
    END IF;
    EXECUTE format('SELECT COALESCE(array_agg(msg_id ORDER BY msg_id), ''{}'') FROM pgmq.%I', 'q_' || instance_queue_name)
    INTO queued_msg_ids;
    IF cardinality(queued_msg_ids) > 0 THEN
        SELECT COALESCE(array_agg(a ORDER BY a), '{}') INTO archived_msg_ids
        FROM pgmq.archive(instance_queue_name, queued_msg_ids) a;
    END IF;
    RETURN archived_msg_ids;
END;
$$;



--
-- Name: async_operation_messages_not_queued_v2("jsonb"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."async_operation_messages_not_queued_v2"("input_messages" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    queue record;
    present bigint[];
    missing jsonb := '[]'::jsonb;
BEGIN
    FOR queue IN
        SELECT m->>'queue_name' AS queue_name,
               array_agg((m->>'msg_id')::bigint) AS msg_ids
        FROM jsonb_array_elements(COALESCE(input_messages, '[]'::jsonb)) m
        GROUP BY m->>'queue_name'
    LOOP
        IF EXISTS (SELECT 1 FROM pgmq.list_queues() q WHERE q.queue_name = queue.queue_name) THEN
            EXECUTE format(
                'SELECT COALESCE(array_agg(msg_id), ''{}'') FROM pgmq.%I WHERE msg_id = ANY($1)',
                pgmq.format_table_name(queue.queue_name, 'q')
            ) INTO present USING queue.msg_ids;
        ELSE
            present := '{}';
        END IF;

        SELECT missing || COALESCE(jsonb_agg(jsonb_build_object('queue_name', queue.queue_name, 'msg_id', id)), '[]'::jsonb)
        INTO missing
        FROM unnest(queue.msg_ids) id
        WHERE id <> ALL (present);
    END LOOP;
    RETURN missing;
END;
$_$;



--
-- Name: async_operation_schedule_next_pending(integer); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."async_operation_schedule_next_pending"("input_stale_threshold_seconds" integer DEFAULT 30) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_entry_id                  uuid;
  v_instance_id               uuid;
  v_async_operation_name      text;
  v_async_operation_version   text;
  v_parent_fsm_name           text;
  v_parent_fsm_version        text;
  v_chosen_workerlet_id       uuid;
BEGIN
  -- Step 1: claim the oldest pending entry (SKIP LOCKED = safe for parallel schedulers).
  SELECT
    async_operation_instance_and_async_operation_workerlet_id,
    async_operation_instance_id,
    async_operation_name,
    async_operation_version,
    parent_fsm_name,
    parent_fsm_version
  INTO
    v_entry_id,
    v_instance_id,
    v_async_operation_name,
    v_async_operation_version,
    v_parent_fsm_name,
    v_parent_fsm_version
  FROM fsm_core.async_operation_instance_and_async_operation_workerlet
  WHERE status = 'pending'
  ORDER BY created_at
  FOR UPDATE SKIP LOCKED
  LIMIT 1;

  IF v_entry_id IS NULL THEN
    RETURN false;
  END IF;

  -- Step 2: pick the best available workerlet.
  --   Filter: heartbeat within threshold (node is alive)
  --           AND supported_async_operations contains this operation
  --           AND active_pid_number < max_pid_number (has a free slot)
  --   Score:  most available slots first (max_pid_number - active_pid_number DESC)
  SELECT async_operation_workerlet_id
  INTO v_chosen_workerlet_id
  FROM fsm_core.async_operation_workerlet
  WHERE
    last_heartbeat > fsm_core.tx_now() - (input_stale_threshold_seconds || ' seconds')::interval
    AND active_pid_number < max_pid_number
    AND supported_async_operations @> jsonb_build_array(
          jsonb_build_object(
            'async_operation_name',    v_async_operation_name,
            'async_operation_version', v_async_operation_version,
            'parent_fsm_name',         v_parent_fsm_name,
            'parent_fsm_version',      v_parent_fsm_version
          )
        )
  ORDER BY (max_pid_number - active_pid_number) DESC
  LIMIT 1;

  IF v_chosen_workerlet_id IS NULL THEN
    -- No capable workerlet right now — leave status=pending, retry on next cycle.
    RETURN false;
  END IF;

  -- Step 3: assign the entry to the chosen workerlet.
  UPDATE fsm_core.async_operation_instance_and_async_operation_workerlet
  SET
    status                       = 'scheduled',
    async_operation_workerlet_id = v_chosen_workerlet_id,
    scheduled_at                 = fsm_core.tx_now()
  WHERE async_operation_instance_and_async_operation_workerlet_id = v_entry_id;

  -- Step 4: wake the workerlet via pg_notify.
  -- Prefix must keep prefix + uuid within PostgreSQL's 63-byte channel-name
  -- limit (pg_notify errors above it). Must match
  -- asyncOperationWorkerletNotifyChannel in fsm-core-db-ts.
  PERFORM pg_notify(
    'async_op_workerlet_work_' || v_chosen_workerlet_id::text,
    v_instance_id::text
  );

  RETURN true;
END;
$$;



--
-- Name: build_nested_json_recursive("text"[]); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."build_nested_json_recursive"("paths" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  result JSONB := '{}'::JSONB;
  path TEXT;
  sorted_paths TEXT[];
BEGIN
  -- Handle NULL input
  IF paths IS NULL THEN
    RETURN result;
  END IF;

  -- Sort paths by their character length (shorter paths first).
  -- Also filter out NULL or empty-string elements to avoid creating "null" keys.
  SELECT array_agg(p) INTO sorted_paths
  FROM (
    SELECT p
    FROM unnest(paths) AS p
    WHERE p IS NOT NULL AND trim(p) <> ''
    ORDER BY char_length(p) ASC
  ) s;

  -- If nothing remains after filtering, return empty object
  IF sorted_paths IS NULL THEN
    RETURN result;
  END IF;

  FOREACH path IN ARRAY sorted_paths LOOP
    result := fsm_core.jsonb_deep_merge(a := result, b := fsm_core.path_string_to_jsonb(path := path));
  END LOOP;

  RETURN result;
END;
$$;



--
-- Name: check_fsm_circular_dependency(); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."check_fsm_circular_dependency"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    loop_detected BOOLEAN;
BEGIN
    IF NEW.parent_fsm_name = NEW.child_fsm_name
       AND NEW.parent_fsm_version = NEW.child_fsm_version THEN
        RAISE EXCEPTION 'Circular dependency: FSM (% %) cannot depend on itself.',
            NEW.parent_fsm_name, NEW.parent_fsm_version;
    END IF;

    -- Walk downstream from NEW.child; if we reach NEW.parent a cycle exists.
    WITH RECURSIVE fsm_graph AS (
        SELECT child_fsm_name, child_fsm_version
        FROM fsm_core.fsm_dependencies
        WHERE parent_fsm_name    = NEW.child_fsm_name
          AND parent_fsm_version = NEW.child_fsm_version

        UNION ALL

        SELECT d.child_fsm_name, d.child_fsm_version
        FROM fsm_core.fsm_dependencies d
        JOIN fsm_graph g
          ON d.parent_fsm_name    = g.child_fsm_name
         AND d.parent_fsm_version = g.child_fsm_version
    )
    SELECT EXISTS (
        SELECT 1 FROM fsm_graph
        WHERE child_fsm_name    = NEW.parent_fsm_name
          AND child_fsm_version = NEW.parent_fsm_version
    ) INTO loop_detected;

    IF loop_detected THEN
        RAISE EXCEPTION 'Circular dependency: linking (% %) -> (% %) creates an infinite loop.',
            NEW.parent_fsm_name, NEW.parent_fsm_version,
            NEW.child_fsm_name,  NEW.child_fsm_version;
    END IF;

    RETURN NEW;
END;
$$;



--
-- Name: check_registry_and_working_for_async_actors_for_fsm_instance_an("jsonb", "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."check_registry_and_working_for_async_actors_for_fsm_instance_an"("input_async_actors" "jsonb", "input_fsm_name" "text", "input_fsm_version" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_actor           record;
  v_non_working_actors jsonb := '[]'::jsonb;
  v_found           boolean;
BEGIN
  FOR v_actor IN
    SELECT
      elem->>'src'        AS src,
      elem->>'fsmVersion' AS fsm_version
    FROM jsonb_array_elements(input_async_actors) AS elem
  LOOP
    SELECT EXISTS (
      SELECT 1
      FROM fsm_core.async_operation_instance_and_async_operation_workerlet
      WHERE parent_fsm_name           = input_fsm_name
        AND parent_fsm_version        = input_fsm_version
        AND async_operation_name      = v_actor.src
        AND async_operation_version   = v_actor.fsm_version
        AND status IN ('pending', 'scheduled')
    ) INTO v_found;

    IF NOT v_found THEN
      v_non_working_actors := v_non_working_actors || jsonb_build_array(
        jsonb_build_object(
          'src',        v_actor.src,
          'fsmVersion', v_actor.fsm_version
        )
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'all_working',        jsonb_array_length(v_non_working_actors) = 0,
    'non_working_actors', v_non_working_actors,
    'fsm_name',           input_fsm_name,
    'fsm_version',        input_fsm_version
  );
END;
$$;



--
-- Name: check_registry_for_async_actors("jsonb", "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."check_registry_for_async_actors"("input_async_actors" "jsonb", "input_fsm_name" "text", "input_fsm_version" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_actor          record;
  v_missing_actors jsonb := '[]'::jsonb;
  v_found          boolean;
BEGIN
  FOR v_actor IN
    SELECT
      elem->>'src'        AS src,
      elem->>'fsmVersion' AS fsm_version
    FROM jsonb_array_elements(input_async_actors) AS elem
  LOOP
    SELECT EXISTS (
      SELECT 1
      FROM fsm_core.async_operation_meta
      WHERE parent_fsm_name       = input_fsm_name
        AND parent_fsm_version    = input_fsm_version
        AND async_operation_name  = v_actor.src
        AND async_operation_version = v_actor.fsm_version
    ) INTO v_found;

    IF NOT v_found THEN
      v_missing_actors := v_missing_actors || jsonb_build_array(
        jsonb_build_object(
          'src',        v_actor.src,
          'fsmVersion', v_actor.fsm_version
        )
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'all_registered', jsonb_array_length(v_missing_actors) = 0,
    'missing_actors', v_missing_actors,
    'fsm_name',       input_fsm_name,
    'fsm_version',    input_fsm_version
  );
END;
$$;



--
-- Name: claim_pending_async_operation_events_for_workers_v2("jsonb"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."claim_pending_async_operation_events_for_workers_v2"("input_workers" "jsonb") RETURNS SETOF "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    worker jsonb;
    computed_queue_name text;
    queue_exists boolean;
    msg pgmq.message_record;
BEGIN
    FOR worker IN SELECT * FROM jsonb_array_elements(input_workers)
    LOOP
        computed_queue_name := fsm_core.compute_async_operation_queue_name_v2(
            worker->>'parent_fsm_name', worker->>'parent_fsm_version',
            worker->>'async_operation_type', worker->>'async_operation_name',
            worker->>'async_operation_version', worker->>'async_operation_language'
        );

        SELECT EXISTS (
            SELECT 1 FROM pgmq.meta WHERE queue_name = computed_queue_name
        ) INTO queue_exists;

        IF NOT queue_exists THEN
            CONTINUE;
        END IF;

        FOR msg IN
            SELECT * FROM pgmq.read(computed_queue_name, 30, 1)
        LOOP
            RETURN NEXT jsonb_build_object(
                'parentFsmName', worker->>'parent_fsm_name',
                'parentFsmVersion', worker->>'parent_fsm_version',
                'asyncOperationType', worker->>'async_operation_type',
                'asyncOperationName', worker->>'async_operation_name',
                'asyncOperationVersion', worker->>'async_operation_version',
                'asyncOperationLanguage', worker->>'async_operation_language',
                'input', msg.message->'eventData'->'eventPayload',
                'instanceId', msg.message->>'sendToParentQueueId',
                'correlationId', msg.msg_id::text,
                'asyncOperationQueueName', computed_queue_name,
                'asyncOperationQueueType', worker->>'async_operation_type',
                'asyncOperationQueueVersion', worker->>'async_operation_version',
                'msgId', msg.msg_id,
                'eventName', msg.message->>'sendToParentQueueIdEventName',
                'eventActionType', msg.message->'eventData'->>'actionType',
                'eventDelay', COALESCE((msg.message->>'queueMsgDelay')::integer, 0),
                'sendToParentQueueId', msg.message->>'sendToParentQueueId',
                'sendToParentQueueIdEventName', msg.message->>'sendToParentQueueIdEventName'
            );
        END LOOP;
    END LOOP;

    RETURN;
END;
$$;



--
-- Name: claim_pending_async_operation_events_with_capacity_v2("jsonb"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."claim_pending_async_operation_events_with_capacity_v2"("input_workers" "jsonb") RETURNS SETOF "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    worker jsonb;
    computed_queue_name text;
    queue_exists boolean;
    claim_qty integer;
    claim_vt integer;
    msg pgmq.message_record;
BEGIN
    FOR worker IN SELECT * FROM jsonb_array_elements(input_workers)
    LOOP
        claim_qty := COALESCE((worker->>'qty')::integer, 0);
        IF claim_qty <= 0 THEN
            CONTINUE;
        END IF;
        claim_vt := GREATEST(COALESCE((worker->>'vt_seconds')::integer, 30), 1);

        computed_queue_name := fsm_core.compute_async_operation_queue_name_v2(
            worker->>'parent_fsm_name', worker->>'parent_fsm_version',
            worker->>'async_operation_type', worker->>'async_operation_name',
            worker->>'async_operation_version', worker->>'async_operation_language'
        );
        SELECT EXISTS (
            SELECT 1 FROM pgmq.meta WHERE queue_name = computed_queue_name
        ) INTO queue_exists;
        IF NOT queue_exists THEN
            CONTINUE;
        END IF;

        FOR msg IN
            SELECT * FROM pgmq.read(computed_queue_name, claim_vt, claim_qty)
        LOOP
            RETURN NEXT jsonb_build_object(
                'parentFsmName', worker->>'parent_fsm_name',
                'parentFsmVersion', worker->>'parent_fsm_version',
                'asyncOperationType', worker->>'async_operation_type',
                'asyncOperationName', worker->>'async_operation_name',
                'asyncOperationVersion', worker->>'async_operation_version',
                'asyncOperationLanguage', worker->>'async_operation_language',
                'input', msg.message->'eventData'->'eventPayload',
                'instanceId', msg.message->>'sendToParentQueueId',
                'correlationId', msg.msg_id::text,
                'asyncOperationQueueName', computed_queue_name,
                'asyncOperationQueueType', worker->>'async_operation_type',
                'asyncOperationQueueVersion', worker->>'async_operation_version',
                'msgId', msg.msg_id,
                'readCount', msg.read_ct,
                'eventName', msg.message->>'sendToParentQueueIdEventName',
                'eventActionType', msg.message->'eventData'->>'actionType',
                'eventDelay', COALESCE((msg.message->>'queueMsgDelay')::integer, 0),
                'sendToParentQueueId', msg.message->>'sendToParentQueueId',
                'sendToParentQueueIdEventName', msg.message->>'sendToParentQueueIdEventName'
            );
        END LOOP;
    END LOOP;
    RETURN;
END;
$$;



--
-- Name: claim_scheduled_for_async_operation_workerlet("uuid"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."claim_scheduled_for_async_operation_workerlet"("input_workerlet_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  WITH claimed AS (
    DELETE FROM fsm_core.async_operation_instance_and_async_operation_workerlet
    WHERE async_operation_instance_and_async_operation_workerlet_id = (
      SELECT async_operation_instance_and_async_operation_workerlet_id
      FROM fsm_core.async_operation_instance_and_async_operation_workerlet
      WHERE status = 'scheduled'
        AND async_operation_workerlet_id = input_workerlet_id
      ORDER BY scheduled_at
      FOR UPDATE SKIP LOCKED
      LIMIT 1
    )
    RETURNING *
  )
  SELECT row_to_json(claimed.*)::jsonb INTO v_result FROM claimed;
  RETURN v_result;
END;
$$;



--
-- Name: claim_scheduled_for_fsmlet("uuid"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."claim_scheduled_for_fsmlet"("input_fsmlet_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_entry_id      uuid;
  v_instance_id   uuid;
  v_fsm_name      text;
  v_fsm_version   text;
  v_dispatch_type text;
BEGIN
  -- Claim one scheduled entry for this fsmlet (SKIP LOCKED = safe for parallel coroutines).
  SELECT
    fsm_instance_and_fsm_workerlet_id,
    fsm_instance_id,
    fsm_name,
    fsm_version,
    dispatch_type
  INTO v_entry_id, v_instance_id, v_fsm_name, v_fsm_version, v_dispatch_type
  FROM fsm_core.fsm_instance_and_fsm_workerlet
  WHERE status = 'scheduled'
    AND fsm_workerlet_id = input_fsmlet_id
  ORDER BY scheduled_at
  FOR UPDATE SKIP LOCKED
  LIMIT 1;

  IF v_entry_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Delete the row — in-memory activeWorkers map on the fsmlet tracks what's running.
  DELETE FROM fsm_core.fsm_instance_and_fsm_workerlet
  WHERE fsm_instance_and_fsm_workerlet_id = v_entry_id;

  RETURN jsonb_build_object(
    'fsm_instance_and_fsm_workerlet_id', v_entry_id,
    'fsm_instance_id',                   v_instance_id,
    'fsm_name',                          v_fsm_name,
    'fsm_version',                       v_fsm_version,
    'dispatch_type',                     v_dispatch_type
  );
END;
$$;



--
-- Name: compute_async_operation_queue_name_v2("text", "text", "text", "text", "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."compute_async_operation_queue_name_v2"("input_parent_fsm_name" "text", "input_parent_fsm_version" "text", "input_async_operation_type" "text", "input_async_operation_name" "text", "input_async_operation_version" "text", "input_async_operation_language" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    IF input_async_operation_type = 'internalAsyncOperation' THEN
        RETURN input_parent_fsm_name || '_' || input_parent_fsm_version
            || '_' || LEFT(input_async_operation_type, 1) || '_' || input_async_operation_name || '_'
            || LEFT(input_async_operation_language, 1);
    ELSIF input_async_operation_type = 'sharedAsyncOperation' THEN
        RETURN LEFT(input_parent_fsm_name, 1) || '_' || input_parent_fsm_version
            || '_' || LEFT(input_async_operation_type, 1) || '_' || input_async_operation_name || '_'
            || input_async_operation_language;
    ELSE
        RAISE EXCEPTION 'compute_async_operation_queue_name_v2: unsupported input_async_operation_type: %', input_async_operation_type;
    END IF;
END;
$$;



--
-- Name: compute_child_exit_set_v1("public"."ltree", "public"."ltree"[]); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."compute_child_exit_set_v1"("transition_domain_lca" "public"."ltree", "state_node_set" "public"."ltree"[]) RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  st ltree;
  result TEXT[] := ARRAY[]::TEXT[];
BEGIN
  
  FOREACH st IN ARRAY state_node_set LOOP
    -- use ltree descendant operator: left <@ right (st <@ domain) means st is contained by domain
    IF st <@ transition_domain_lca THEN
      result := result || st::text;
    END IF;
  END LOOP;

  RETURN result;
END;
$$;



SET default_tablespace = '';

SET default_table_access_method = "heap";

--
-- Name: fsm_transitions; Type: TABLE; Schema: fsm_core; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "fsm_core"."fsm_transitions" (
    "id" integer NOT NULL,
    "actions" "jsonb",
    "cond" "jsonb",
    "event_type" "text" NOT NULL,
    "source" "text" NOT NULL,
    "computed_sanitized_source_ltree" "public"."ltree" NOT NULL,
    "target" "text"[],
    "computed_sanitized_target_ltree_array" "public"."ltree"[],
    "reenter" boolean DEFAULT false,
    "computed_transition_domain_lca" "text",
    "fsm_name" "text",
    "fsm_version" "text"
);



--
-- Name: compute_entry_actions_v1("fsm_core"."fsm_transitions", "text", "text", boolean); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."compute_entry_actions_v1"("transition_record" "fsm_core"."fsm_transitions", "fsm_name_param" "text", "fsm_version_param" "text", "is_initial_transition" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    sanitized_source_ltree LTREE;
    sanitized_target_ltree_array LTREE[];
    sanitized_target_state TEXT;
    transition_domain_lca ltree;
    reenter_flag BOOLEAN;
    effective_target_states_ltree_array LTREE[];
    sanitized_effective_target_state TEXT;
    ancestors TEXT[];
    ancestors_result RECORD;
    domain_type TEXT;
    child_result RECORD;
    states_to_enter TEXT[];
    states_for_default_entry TEXT[];
    common_states TEXT[] := '{}';
    state_to_check TEXT;
    entry_actions_result JSONB;
    initial_actions_for_common_states_result JSONB;
    resolve_state_value_result JSONB;
    final_result JSONB;
BEGIN

   -- if is_initial_transition true 
   -- then return empty result
    IF is_initial_transition THEN
          select fsm_core.resolve_state_value_v1(input_json := '{}'::jsonb, input_fsm_name := fsm_name_param, input_fsm_version := fsm_version_param) INTO resolve_state_value_result;
        --   states_to_enter := resolve_state_value_result->'all_nodes';
          states_to_enter := array(
                SELECT jsonb_array_elements_text(resolve_state_value_result->'all_nodes')
            );

          SELECT fsm_core.get_entry_actions_v1(p_state_paths := states_to_enter, p_fsm_name := fsm_name_param, p_fsm_version := fsm_version_param) INTO entry_actions_result;
          RETURN jsonb_build_object(
                'states_to_enter', states_to_enter,
                'states_for_default_entry', '[]'::jsonb,
                'common_states', '[]'::jsonb,
                'entry_actions_for_states_to_enter', entry_actions_result::jsonb,
                'initial_actions_for_common_states', '[]'::jsonb
          );
    END IF;
    
    -- If no transition found, return empty result
    IF transition_record IS NULL THEN
        RETURN jsonb_build_object(
            'states_to_enter', '[]'::jsonb,
            'states_for_default_entry', '[]'::jsonb,
            'common_states', '[]'::jsonb,
            'entry_actions_for_states_to_enter', '[]'::jsonb,
            'initial_actions_for_common_states', '[]'::jsonb
        );
    END IF;
    
    
    sanitized_source_ltree := transition_record.computed_sanitized_source_ltree;
   
    sanitized_target_ltree_array := transition_record.computed_sanitized_target_ltree_array;
   

    RAISE NOTICE 'Calculating Transition Domain LCA from transition_record: %', transition_record;

    transition_domain_lca := fsm_core.sql_lca_from_array(
        paths := ARRAY[transition_record.computed_sanitized_source_ltree::ltree] || transition_record.computed_sanitized_target_ltree_array
    );

    reenter_flag := COALESCE((transition_record.reenter)::BOOLEAN, FALSE);
    
    -- Part 1 : add all target state node and call addDescendantStatesToEnter to add all inital and node childern nodes
    -- Call getStatesForEntry with the transition record and fsm parameters
    -- result := getStatesForEntry(source_state, target_states_json, transition_domain_lca::TEXT, reenter_flag, fsm_name_param, fsm_version_param);
    -- above line is and getStatesForEntry fn replaced with below code
    RAISE NOTICE 'sanitized_target_ltree_array: %', sanitized_target_ltree_array;
    IF sanitized_target_ltree_array IS NOT NULL AND array_length(sanitized_target_ltree_array, 1) > 0 THEN
        FOR sanitized_target_state IN SELECT unnest(sanitized_target_ltree_array)
        LOOP
            
            -- Apply the logic from the JavaScript code
            IF (
                -- if the target is different than the source then it will *definitely* be entered
                sanitized_source_ltree::TEXT != sanitized_target_state::TEXT OR
                -- we know that the domain can't lie within the source
                -- if it's different than the source then it's outside of it and it means that the target has to be entered as well
                sanitized_source_ltree::TEXT != transition_domain_lca::TEXT OR
                -- reentering transitions always enter the target, even if it's the source itself
                reenter_flag
            ) THEN
                
                -- Add to states_to_enter if not already present
                
                    states_to_enter := array_append(states_to_enter, sanitized_target_state);
                
                    states_for_default_entry := array_append(states_for_default_entry, sanitized_target_state);
                
                    RAISE NOTICE 'states_to_enter: %', states_to_enter;
            END IF;

            RAISE NOTICE 'Before fsm_core.get_descendant_states_for_entry_v1 for sanitized_target_state: %', sanitized_target_state;
            RAISE NOTICE 'states_to_enter: %', states_to_enter;
            RAISE NOTICE 'states_for_default_entry: %', states_for_default_entry;
            
            -- call fsm_core.get_descendant_states_for_entry_v1 for each child state
            child_result := fsm_core.get_descendant_states_for_entry_v1(input_state_id := sanitized_target_state::text, fsm_name_param := fsm_name_param, fsm_version_param := fsm_version_param);
            RAISE NOTICE 'After fsm_core.get_descendant_states_for_entry_v1 for sanitized_target_state: %', sanitized_target_state;
            RAISE NOTICE 'child_result: %', child_result;
            states_to_enter := array_cat(states_to_enter, child_result.descendant_states_to_enter);
            states_for_default_entry := array_cat(states_for_default_entry, child_result.descendant_states_for_default_entry);
            RAISE NOTICE 'states_to_enter: %', states_to_enter;
            RAISE NOTICE 'states_for_default_entry: %', states_for_default_entry;
        END LOOP;
    END IF;

    -- Part 2 : add all inbetween state nodes from domain to target state node

    SELECT type INTO domain_type FROM fsm_core.fsm_states
                WHERE computed_state_key_ltree = transition_domain_lca
                  AND fsm_name = fsm_name_param
                  AND fsm_version = fsm_version_param;

    -- TODO : pending fn of getEffectiveTargetStates would be transition_json -> 'target';
    effective_target_states_ltree_array = transition_record.computed_sanitized_target_ltree_array;
    RAISE NOTICE 'effective_target_states_ltree_array: %', effective_target_states_ltree_array;
    -- for (const s of effective_target_states) {
    --   const ancestors = get_proper_ancestors(s, domain);
    --   if (domain?.type === 'parallel') {
    --     ancestors.push(domain);
    --   }
    --   fsm_core.get_ancestor_states_for_entry_v1(
    --     statesToEnter,
    --     historyValue,
    --     statesForDefaultEntry,
    --     ancestors,
    --     !t.source.parent && t.reenter ? undefined : domain
    --   );
    -- }

    IF effective_target_states_ltree_array IS NOT NULL AND array_length(effective_target_states_ltree_array, 1) > 0 THEN
        FOR sanitized_effective_target_state IN SELECT unnest(effective_target_states_ltree_array)
        LOOP

            

            -- Get ancestors for s and domain
            ancestors := fsm_core.get_proper_ancestors(state_path_ltree := sanitized_effective_target_state::TEXT, to_state_path_ltree := transition_domain_lca::TEXT);

            -- If domain is parallel, append domain to ancestors
            IF domain_type = 'parallel' THEN
                ancestors := array_append(ancestors, transition_domain_lca::TEXT);
            END IF;

            
            ancestors_result := fsm_core.get_ancestor_states_for_entry_v1(
                ancestors := ancestors,
                reentrancy_domain := CASE WHEN transition_record.source IS NULL AND transition_record.reenter THEN NULL ELSE transition_domain_lca::TEXT END,
                fsm_name_param := fsm_name_param,
                fsm_version_param := fsm_version_param
            );

            states_to_enter := array_cat(states_to_enter, ancestors_result.ancestor_states_to_enter);

        END LOOP;
    END IF;

    RAISE NOTICE 'Final states_to_enter before dedup: %', states_to_enter;
    RAISE NOTICE 'Final states_for_default_entry before dedup: %', states_for_default_entry;
  
    
    -- Find common elements between states_to_enter and states_for_default_entry
    FOR state_to_check IN SELECT unnest(states_to_enter)
    LOOP
        -- Check if statesForDefaultEntry has this stateNodeToEnter
        IF state_to_check = ANY(states_for_default_entry) THEN
            -- Add to common_states (actions array equivalent)
            common_states := array_append(common_states, state_to_check);
        END IF;
    END LOOP;
    
    -- Log the common states found
    RAISE NOTICE 'Common states found: %', common_states;
        
        
  

    -- Get entry actions for states_to_enter
    SELECT fsm_core.get_entry_actions_v1(p_state_paths := states_to_enter, p_fsm_name := fsm_name_param, p_fsm_version := fsm_version_param) INTO entry_actions_result;

    -- -- Get entry actions for states_for_default_entry
    -- SELECT fsm_core.get_entry_actions_v1(states_for_default_entry, fsm_name_param, fsm_version_param) INTO default_entry_actions_result;
    -- Get entry actions for the common states
    IF array_length(common_states, 1) > 0 THEN
        SELECT fsm_core.get_initial_actions_v1(p_state_paths := common_states, p_fsm_name := fsm_name_param, p_fsm_version := fsm_version_param) INTO initial_actions_for_common_states_result;
    END IF;


    -- Build the final result containing both arrays and their respective actions
    final_result := jsonb_build_object(
        'states_to_enter', to_jsonb(states_to_enter),
        'states_for_default_entry', to_jsonb(states_for_default_entry),
        'common_states', to_jsonb(common_states),
        'entry_actions_for_states_to_enter', entry_actions_result,
        'initial_actions_for_common_states', initial_actions_for_common_states_result
    );

    RETURN final_result;
END;
$$;



--
-- Name: compute_entry_set_v2("fsm_core"."fsm_transitions", "text", "text", boolean); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."compute_entry_set_v2"("transition_record" "fsm_core"."fsm_transitions", "fsm_name_param" "text", "fsm_version_param" "text", "is_initial_transition" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
-- XState's computeEntrySet (packages/core/src/stateUtils.ts) for one
-- transition:
--
--   for (const t of transitions) {
--     const domain = getTransitionDomain(t, historyValue);
--     for (const s of t.target || []) {                        // Part 1
--       if (t.source !== s || t.source !== domain || t.reenter) {
--         statesToEnter.add(s);
--         statesForDefaultEntry.add(s);
--       }
--       addDescendantStatesToEnter(s, historyValue, statesForDefaultEntry, statesToEnter);
--     }
--     for (const s of getEffectiveTargetStates(t, historyValue)) {  // Part 2
--       const ancestors = getProperAncestors(s, domain);
--       if (domain?.type === 'parallel') ancestors.push(domain);
--       addAncestorStatesToEnter(statesToEnter, historyValue, statesForDefaultEntry,
--         ancestors, !t.source.parent && t.reenter ? undefined : domain);
--     }
--   }
--
-- Returned as lists: states_to_enter (statesToEnter) and
-- states_for_default_entry (statesForDefaultEntry), for enter_states_v2. The
-- domain is the stored computed_transition_domain_lca
-- (get_transition_domain_v2). History states are not supported.
DECLARE
    sanitized_source_ltree LTREE;
    sanitized_target_ltree_array LTREE[];
    sanitized_target_state TEXT;
    transition_domain_lca ltree;
    reenter_flag BOOLEAN;
    effective_target_states_ltree_array LTREE[];
    sanitized_effective_target_state TEXT;
    ancestors TEXT[];
    ancestors_result RECORD;
    domain_type TEXT;
    source_is_root BOOLEAN;
    child_result RECORD;
    states_to_enter TEXT[];
    states_for_default_entry TEXT[];
    root_path ltree;
    final_result JSONB;
BEGIN

    -- The initial step. XState's initialMicrostep runs this same computeEntrySet
    -- with a synthetic transition:
    --
    --   { target: [...getInitialStateNodes(root)], source: root, reenter: true, actions: [] }
    --
    -- It has no domain (it re-enters, and the root has no proper ancestor), so
    -- every target is entered and is a default entry, and the descendant and
    -- ancestor steps add nothing new: the targets are the root and its whole
    -- initial chain. So the result is just getInitialStateNodes(root), which
    -- fsm_get_initial_state_nodes_v2 computes directly.
    --
    -- Why not build that synthetic transition and run it through the general
    -- path below, as XState does: the answer is already known, and the first
    -- event of every instance would then depend on all of the general entry
    -- code (descendants, ancestors, reentrancy) and its queries, for nothing.
    IF is_initial_transition THEN
          SELECT fs.computed_state_key_ltree INTO root_path
          FROM fsm_core.fsm_states fs
          WHERE fs.fsm_name = fsm_name_param
            AND fs.fsm_version = fsm_version_param
            AND fs.parent_node IS NULL;
          -- statesToEnter = getInitialStateNodes(root): the root, a compound's
          -- initial target, and every child of a parallel state, recursively.
          states_to_enter := COALESCE(
              fsm_core.fsm_get_initial_state_nodes_v2(input_fsm_name := fsm_name_param, input_fsm_version := fsm_version_param, input_state_path := root_path),
              ARRAY[]::TEXT[]
          );

          RETURN jsonb_build_object(
                'states_to_enter', states_to_enter,
                -- Every target is a default entry, the root included
                -- (enterStates' `if (isInitial)
                -- statesForDefaultEntry.add(machine.root)`), so each one's
                -- initial actions run.
                'states_for_default_entry', states_to_enter
          );
    END IF;
    
    -- No transition: nothing is entered.
    IF transition_record IS NULL THEN
        RETURN jsonb_build_object(
            'states_to_enter', '[]'::jsonb,
            'states_for_default_entry', '[]'::jsonb
        );
    END IF;
    
    
    sanitized_source_ltree := transition_record.computed_sanitized_source_ltree;
   
    sanitized_target_ltree_array := transition_record.computed_sanitized_target_ltree_array;
   

    RAISE NOTICE 'Skipped Calculating Transition Domain LCA from transition_record: %', transition_record;

    RAISE NOTICE 'Fetching Transition Domain LCA from transition_record: %', transition_record;

    transition_domain_lca := transition_record.computed_transition_domain_lca;


    reenter_flag := COALESCE((transition_record.reenter)::BOOLEAN, FALSE);
    
    -- Part 1: for (const s of t.target || []) { ... }
    RAISE NOTICE 'sanitized_target_ltree_array: %', sanitized_target_ltree_array;
    IF sanitized_target_ltree_array IS NOT NULL AND array_length(sanitized_target_ltree_array, 1) > 0 THEN
        FOR sanitized_target_state IN SELECT unnest(sanitized_target_ltree_array)
        LOOP
            
            IF (
                -- if (t.source !== s || t.source !== domain || t.reenter):
                -- if the target is different than the source then it will *definitely* be entered
                sanitized_source_ltree::TEXT != sanitized_target_state::TEXT OR
                -- we know that the domain can't lie within the source
                -- if it's different than the source then it's outside of it and it means that the target has to be entered as well
                sanitized_source_ltree::TEXT != transition_domain_lca::TEXT OR
                -- reentering transitions always enter the target, even if it's the source itself
                reenter_flag
            ) THEN
                
                
                    states_to_enter := array_append(states_to_enter, sanitized_target_state);
                
                    states_for_default_entry := array_append(states_for_default_entry, sanitized_target_state);
                
                    RAISE NOTICE 'states_to_enter: %', states_to_enter;
            END IF;

            RAISE NOTICE 'Before fsm_core.get_descendant_states_for_entry_v2 for sanitized_target_state: %', sanitized_target_state;
            RAISE NOTICE 'states_to_enter: %', states_to_enter;
            RAISE NOTICE 'states_for_default_entry: %', states_for_default_entry;
            
            -- addDescendantStatesToEnter(s, historyValue, statesForDefaultEntry, statesToEnter);
            child_result := fsm_core.get_descendant_states_for_entry_v2(input_state_id := sanitized_target_state::text, fsm_name_param := fsm_name_param, fsm_version_param := fsm_version_param);
            RAISE NOTICE 'After fsm_core.get_descendant_states_for_entry_v2 for sanitized_target_state: %', sanitized_target_state;
            RAISE NOTICE 'child_result: %', child_result;
            states_to_enter := array_cat(states_to_enter, child_result.descendant_states_to_enter);
            states_for_default_entry := array_cat(states_for_default_entry, child_result.descendant_states_for_default_entry);
            RAISE NOTICE 'states_to_enter: %', states_to_enter;
            RAISE NOTICE 'states_for_default_entry: %', states_for_default_entry;
        END LOOP;
    END IF;

    -- Part 2: for (const s of getEffectiveTargetStates(t, historyValue)) { ... }

    SELECT type INTO domain_type FROM fsm_core.fsm_states
                WHERE computed_state_key_ltree = transition_domain_lca
                  AND fsm_name = fsm_name_param
                  AND fsm_version = fsm_version_param;
    

    -- getEffectiveTargetStates(t, historyValue): the targets themselves; history
    -- states, which it would resolve, are not supported.
    effective_target_states_ltree_array = transition_record.computed_sanitized_target_ltree_array;
    RAISE NOTICE 'effective_target_states_ltree_array: %', effective_target_states_ltree_array;

    -- !t.source.parent: the transition's source is the root (#506).
    source_is_root := EXISTS (
        SELECT 1 FROM fsm_core.fsm_states fs
        WHERE fs.fsm_name = fsm_name_param
          AND fs.fsm_version = fsm_version_param
          AND fs.computed_state_key_ltree = sanitized_source_ltree
          AND fs.parent_node IS NULL
    );

    IF effective_target_states_ltree_array IS NOT NULL AND array_length(effective_target_states_ltree_array, 1) > 0 THEN
        FOR sanitized_effective_target_state IN SELECT unnest(effective_target_states_ltree_array)
        LOOP

            -- const ancestors = getProperAncestors(s, domain);
            IF transition_domain_lca IS NULL THEN
                -- No domain: getProperAncestors(s, undefined) is every ancestor
                -- state, the root included, nearest first. get_proper_ancestors
                -- stops at once on a NULL end, and walking the path would also
                -- yield the labels of a root id with dots, so take them from
                -- the FSM's states (#506).
                SELECT COALESCE(array_agg(fs.computed_state_key_ltree::TEXT ORDER BY nlevel(fs.computed_state_key_ltree) DESC), ARRAY[]::TEXT[])
                INTO ancestors
                FROM fsm_core.fsm_states fs
                WHERE fs.fsm_name = fsm_name_param
                  AND fs.fsm_version = fsm_version_param
                  AND fsm_core.is_descendant(input_child := sanitized_effective_target_state::ltree, input_parent := fs.computed_state_key_ltree);
            ELSE
                ancestors := fsm_core.get_proper_ancestors(state_path_ltree := sanitized_effective_target_state::TEXT, to_state_path_ltree := transition_domain_lca::TEXT);
            END IF;

            -- if (domain?.type === 'parallel') ancestors.push(domain);
            IF domain_type = 'parallel' THEN
                ancestors := array_append(ancestors, transition_domain_lca::TEXT);
            END IF;

            
            -- addAncestorStatesToEnter(statesToEnter, historyValue,
            --   statesForDefaultEntry, ancestors, reentrancyDomain)
            ancestors_result := fsm_core.get_ancestor_states_for_entry_v2(
                ancestors := ancestors,
                -- !t.source.parent && t.reenter ? undefined : domain (#506)
                reentrancy_domain := CASE WHEN source_is_root AND reenter_flag THEN NULL ELSE transition_domain_lca::TEXT END,
                fsm_name_param := fsm_name_param,
                fsm_version_param := fsm_version_param
            );

            states_to_enter := array_cat(states_to_enter, ancestors_result.ancestor_states_to_enter);
            -- Regions of a parallel ancestor entered on the way also enter their
            -- initial states by default (addAncestorStatesToEnter calls
            -- addDescendantStatesToEnter with statesForDefaultEntry), so those
            -- states' initial actions run too (#506).
            states_for_default_entry := array_cat(states_for_default_entry, ancestors_result.ancestor_states_for_default_entry);

        END LOOP;
    END IF;

    RAISE NOTICE 'Final states_to_enter before dedup: %', states_to_enter;
    RAISE NOTICE 'Final states_for_default_entry before dedup: %', states_for_default_entry;
  
    
    -- Empty arrays, not JSON null, when nothing is entered (a targetless
    -- transition): enter_states_v2 expands states_to_enter (#506).
    final_result := jsonb_build_object(
        'states_to_enter', COALESCE(to_jsonb(states_to_enter), '[]'::jsonb),
        'states_for_default_entry', COALESCE(to_jsonb(states_for_default_entry), '[]'::jsonb)
    );

    RETURN final_result;
END;
$$;



--
-- Name: compute_exit_actions_v1("fsm_core"."fsm_transitions", "text"[], "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."compute_exit_actions_v1"("transition_record" "fsm_core"."fsm_transitions", "p_state_node_set" "text"[], "p_fsm_name" "text", "p_fsm_version" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  exit_set_result TEXT[];
  actions_result JSONB;
BEGIN

  
  -- If no transition found, return empty array
  IF transition_record IS NULL THEN
      RETURN jsonb_build_object(
              'exit_nodes', '[]'::JSONB,
              'exit_actions', '[]'::JSONB
            );
  END IF;



  RAISE NOTICE 'Transition Record: %', transition_record;
  -- Step 1: Call compute_full_exit_set function
  SELECT fsm_core.compute_full_exit_set_v1(transition_record := transition_record, state_node_set := p_state_node_set) INTO exit_set_result;

  RAISE NOTICE 'Exit Set Result: %', exit_set_result;

  -- Step 2: Call fsm_core.get_exit_actions_v1 with the result from step 1
  SELECT fsm_core.get_exit_actions_v1(p_state_paths := exit_set_result, p_fsm_name := p_fsm_name, p_fsm_version := p_fsm_version) INTO actions_result;

  RAISE NOTICE 'exit_actions Result: %', actions_result;

  -- Return both exit_nodes and exit_actions as a JSON object
  RETURN jsonb_build_object(
    'exit_nodes', exit_set_result,
    'exit_actions', actions_result->'actions'
  );
END;
$$;



--
-- Name: compute_full_exit_set_v1("fsm_core"."fsm_transitions", "text"[]); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."compute_full_exit_set_v1"("transition_record" "fsm_core"."fsm_transitions", "state_node_set" "text"[]) RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  transition_domain_lca ltree;
  state_node_set_ltree ltree[];
  sanitized_source TEXT;
  exit_set TEXT[] := ARRAY[]::TEXT[];
  child_exit TEXT[] := ARRAY[]::TEXT[];
  combined TEXT[];
BEGIN
  IF transition_record IS NULL OR state_node_set IS NULL THEN
    RETURN ARRAY[]::TEXT[];
  END IF;

  
  RAISE NOTICE 'Calculating Transition Domain LCA from transition_record: %', transition_record;


  transition_domain_lca := fsm_core.sql_lca_from_array(
      paths := ARRAY[transition_record.computed_sanitized_source_ltree::ltree] || transition_record.computed_sanitized_target_ltree_array
  );


  state_node_set_ltree = fsm_core.sanitize_text_array_to_ltree_array(input_array := state_node_set);
  -- call child exit set using the domain text (fsm_core.compute_child_exit_set_v1 will sanitize)
  child_exit := fsm_core.compute_child_exit_set_v1(transition_domain_lca := transition_domain_lca, state_node_set := state_node_set_ltree);

  -- sanitize source to compare with LCA in the same normalized form
  sanitized_source := transition_record.computed_sanitized_source_ltree;

  IF sanitized_source IS NOT NULL AND sanitized_source <> '' THEN
    IF transition_domain_lca IS NOT NULL THEN
      IF transition_domain_lca::TEXT = sanitized_source::TEXT THEN
        -- Only add the source_text when the transition JSON has a truthy
        -- "reenter" flag. Use COALESCE to safely cast NULL to false.
        IF COALESCE(transition_record.reenter, 'false')::boolean = true THEN
          exit_set := exit_set || sanitized_source;
        END IF;
      END IF;
    END IF;
  END IF;

  -- combine and deduplicate
  combined := exit_set || child_exit;
  SELECT array_agg(DISTINCT x) INTO combined FROM unnest(combined) AS x WHERE x IS NOT NULL;

  RETURN COALESCE(combined, ARRAY[]::TEXT[]);
END;
$$;



--
-- Name: compute_full_exit_set_v2("fsm_core"."fsm_transitions", "text"[]); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."compute_full_exit_set_v2"("transition_record" "fsm_core"."fsm_transitions", "state_node_set" "text"[]) RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
-- XState's computeExitSet (packages/core/src/stateUtils.ts) for one
-- transition, step by step:
--
--   if (t.target?.length) {
--     const domain = getTransitionDomain(t, historyValue);
--     if (t.reenter && t.source === domain) statesToExit.add(domain);
--     for (const stateNode of stateNodeSet) {
--       if (isDescendant(stateNode, domain)) statesToExit.add(stateNode);
--     }
--   }
DECLARE
  transition_domain_lca ltree;
  sanitized_source ltree;
  state_node ltree;
  exit_set TEXT[] := ARRAY[]::TEXT[];
  child_exit TEXT[] := ARRAY[]::TEXT[];
  combined TEXT[];
BEGIN
  IF transition_record IS NULL OR state_node_set IS NULL THEN
    RETURN ARRAY[]::TEXT[];
  END IF;

  -- if (t.target?.length): a targetless transition exits nothing; XState only
  -- runs its actions (#506).
  IF COALESCE(array_length(transition_record.computed_sanitized_target_ltree_array, 1), 0) = 0 THEN
    RETURN ARRAY[]::TEXT[];
  END IF;

  -- const domain = getTransitionDomain(t, historyValue): stored by the loader
  -- in computed_transition_domain_lca (get_transition_domain_v2). NULL means
  -- no domain (a re-entering transition at the root).
  transition_domain_lca := transition_record.computed_transition_domain_lca;
  sanitized_source := transition_record.computed_sanitized_source_ltree;

  -- if (t.reenter && t.source === domain) statesToExit.add(domain)
  IF COALESCE(transition_record.reenter, false) AND sanitized_source = transition_domain_lca THEN
    exit_set := exit_set || transition_domain_lca::TEXT;
  END IF;

  -- for (const stateNode of stateNodeSet) {
  --   if (isDescendant(stateNode, domain)) statesToExit.add(stateNode);
  -- }
  -- The domain itself stays active unless the transition re-enters it (added
  -- above); no domain (NULL) exits every active state (#506).
  --
  -- Written as a loop to match XState line by line. The same filter as one
  -- query (no faster for an instance's handful of active states):
  --   SELECT COALESCE(array_agg(st::TEXT), ARRAY[]::TEXT[]) INTO child_exit
  --   FROM unnest(fsm_core.sanitize_text_array_to_ltree_array(input_array := state_node_set)) AS st
  --   WHERE fsm_core.is_descendant(input_child := st, input_parent := transition_domain_lca);
  FOREACH state_node IN ARRAY COALESCE(fsm_core.sanitize_text_array_to_ltree_array(input_array := state_node_set), ARRAY[]::ltree[]) LOOP
    IF fsm_core.is_descendant(input_child := state_node, input_parent := transition_domain_lca) THEN
      child_exit := child_exit || state_node::TEXT;
    END IF;
  END LOOP;

  -- statesToExit is a Set: combine and deduplicate.
  combined := exit_set || child_exit;
  SELECT array_agg(DISTINCT x) INTO combined FROM unnest(combined) AS x WHERE x IS NOT NULL;

  RETURN COALESCE(combined, ARRAY[]::TEXT[]);
END;
$$;



--
-- Name: create_api_key("text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."create_api_key"("input_name" "text", "input_role" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pg_temp'
    AS $$
DECLARE
  v_key_prefix text;
  v_key        text;
  v_id         uuid;
BEGIN
  IF input_name IS NULL OR btrim(input_name) = '' THEN
    RAISE EXCEPTION 'create_api_key: name is required' USING ERRCODE = '22023';
  END IF;

  v_key_prefix := CASE input_role
    WHEN 'fsm_admin'    THEN 'pgfsm_admin_'
    WHEN 'fsm_operator' THEN 'pgfsm_op_'
  END;
  IF v_key_prefix IS NULL THEN
    RAISE EXCEPTION 'create_api_key: role must be fsm_admin or fsm_operator, got %', input_role
      USING ERRCODE = '22023';
  END IF;

  v_key := v_key_prefix || encode(
    uuid_send(gen_random_uuid()) || uuid_send(gen_random_uuid()), 'hex');

  INSERT INTO fsm_core.api_keys (name, role, prefix, key_hash)
  VALUES (input_name, input_role, left(v_key, length(v_key_prefix) + 8),
          sha256(convert_to(v_key, 'UTF8')))
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'id', v_id,
    'name', input_name,
    'role', input_role,
    'prefix', left(v_key, length(v_key_prefix) + 8),
    'key', v_key
  );
END;
$$;



--
-- Name: create_async_operation_instance_and_notify_async_operation_sche("uuid", "text", "text", "text", "text", "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."create_async_operation_instance_and_notify_async_operation_sche"("input_async_operation_instance_id" "uuid", "input_async_operation_name" "text", "input_async_operation_version" "text", "input_async_operation_type" "text", "input_parent_fsm_name" "text", "input_parent_fsm_version" "text", "input_async_operation_language" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  INSERT INTO fsm_core.async_operation_instance_and_async_operation_workerlet (
    async_operation_instance_id,
    async_operation_name,
    async_operation_version,
    async_operation_type,
    parent_fsm_name,
    parent_fsm_version,
    async_operation_language
  )
  VALUES (
    input_async_operation_instance_id,
    input_async_operation_name,
    input_async_operation_version,
    input_async_operation_type,
    input_parent_fsm_name,
    input_parent_fsm_version,
    input_async_operation_language
  );

  PERFORM pg_notify(
    'async_operation_scheduler_work',
    input_async_operation_instance_id::text
  );
END;
$$;



--
-- Name: create_fsm_instance_from_name_v2("text", "text", "jsonb", boolean, "uuid", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."create_fsm_instance_from_name_v2"("input_fsm_name" "text", "input_fsm_version" "text", "input_fsm_context" "jsonb", "create_pgmq_queue" boolean DEFAULT true, "input_parent_fsm_instance_id" "uuid" DEFAULT NULL::"uuid", "input_parent_invoke_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    output_queue_created boolean := false;
    output_message text := NULL;
    output_extra_message text := NULL;
    fsm_instance_id uuid;
    send_event_result jsonb := NULL;
    derived_fsm_type text;
    fsm_json_exists boolean;
    fsm_instance_row      fsm_core.fsm_instance;
    declared_context jsonb;
    instance_context jsonb;
BEGIN
    -- 1. Check if fsm_name and fsm_version exist in fsm_core.fsm_json, and
    --    read the definition's static context (SPEC-013, #584).
    SELECT true, fj.fsm_json->'context'
    INTO fsm_json_exists, declared_context
    FROM fsm_core.fsm_json fj
    WHERE fj.fsm_name = input_fsm_name AND fj.fsm_version = input_fsm_version;

    IF NOT COALESCE(fsm_json_exists, false) THEN
        RAISE EXCEPTION 'FSM with name % and version % not found in fsm_core.fsm_json', input_fsm_name, input_fsm_version;
    END IF;

    -- 1.0. The instance's context (SPEC-013): the definition's static context,
    --      when fsm.json has one, shallow-merged with the context it's created
    --      with, which wins (the API payload, or an invoked child FSM's
    --      input). Without a declared context the given one is used as before.
    --      A non-object given context can't be merged: it's dropped with a
    --      warning, and the instance starts from the declared context alone.
    IF jsonb_typeof(declared_context) IS DISTINCT FROM 'object' THEN
        declared_context := NULL;
    END IF;
    IF input_fsm_context IS NULL OR jsonb_typeof(input_fsm_context) = 'null' THEN
        instance_context := COALESCE(declared_context, input_fsm_context);
    ELSIF jsonb_typeof(input_fsm_context) = 'object' THEN
        instance_context := COALESCE(declared_context, '{}'::jsonb) || input_fsm_context;
    ELSE
        RAISE WARNING 'FSM %@%: ignoring a non-object initial context (%); starting from its declared context',
            input_fsm_name, input_fsm_version, jsonb_typeof(input_fsm_context);
        instance_context := COALESCE(declared_context, '{}'::jsonb);
    END IF;

    -- 1.1. Derive fsm_type from fsm_core.fsm_dependencies: a row where this FSM
    -- is a child means it's a childfsm, otherwise it's a top-level fsm.
    IF EXISTS (
        SELECT 1
        FROM fsm_core.fsm_dependencies fd
        WHERE fd.child_fsm_name = input_fsm_name AND fd.child_fsm_version = input_fsm_version
    ) THEN
        derived_fsm_type := 'childfsm';
    ELSE
        derived_fsm_type := 'fsm';
    END IF;

    -- 2. Create new fsm_instance
    INSERT INTO fsm_core.fsm_instance (fsm_name, fsm_version, fsm_type, fsm_instance_context, parent_fsm_instance_id, parent_invoke_id)
    VALUES (input_fsm_name, input_fsm_version, derived_fsm_type, instance_context, input_parent_fsm_instance_id, input_parent_invoke_id)
    RETURNING * INTO fsm_instance_row;

    fsm_instance_id := fsm_instance_row.id;

    -- 3. Insert all transitions into fsm_core.fsm_instance_transitions_auth
    INSERT INTO fsm_core.fsm_instance_transitions_auth (
        fsm_name, fsm_version, fsm_type, fsm_instance_id, fsm_instance_event_type, users, groups, module_tag, meta_info
    )
    SELECT
        t.fsm_name,
        t.fsm_version,
        derived_fsm_type,
        fsm_instance_id,
        t.event_type,
        ARRAY[]::jsonb[], -- users (default empty array)
        ARRAY[]::jsonb[], -- groups (default empty array)
        NULL::jsonb,      -- module_tag (default null)
        NULL::jsonb       -- meta_info (default null)
    FROM fsm_core.fsm_transitions t
    WHERE t.fsm_name = input_fsm_name AND t.fsm_version = input_fsm_version;

    -- 4. Enqueue to fsm_instance_and_fsm_workerlet and notify the fsmscheduler.
    PERFORM fsm_core.enqueue_fsm_dispatch_v2(
        fsm_instance_id,
        input_fsm_name,
        input_fsm_version,
        'start'
    );

    -- 5. Optionally create pgmq queue and send initial event
    IF create_pgmq_queue THEN
        BEGIN
            PERFORM pgmq.create(queue_name := fsm_instance_id::text);
            output_queue_created := true;
            output_message := 'Queue created successfully.';
            -- Try to send initialTransition_event to the queue
            BEGIN
                send_event_result := fsm_core.send_event_to_fsm_queue_with_event_logs_v2(
                    input_fsm_instance_id := fsm_instance_id,
                    input_fsm_instance_id_fsm_type := derived_fsm_type,
                    input_fsm_instance_id_fsm_version := input_fsm_version,
                    input_event_name := 'initialTransition_event',
                    input_event_action_type := 'system',
                    input_event_data := jsonb_build_object('source', 'system'),
                    input_event_delay := 0,
                    input_event_status := 'fsm_started',
                    input_event_output := '{}'::jsonb,
                    input_error_message := NULL,
                    input_execution_started_at := fsm_core.tx_now(),
                    input_execution_duration := NULL,
                    input_execution_finished_at := fsm_core.tx_now()
                );
                output_extra_message := 'initialTransition_event is also sent to queue.';
            EXCEPTION WHEN OTHERS THEN
                output_extra_message := SQLERRM;
            END;
        EXCEPTION WHEN OTHERS THEN
            output_queue_created := false;
            output_message := SQLERRM;
        END;
    ELSE
        output_queue_created := false;
        output_message := 'queue_created is false and no queue is created.';
        output_extra_message := NULL;
    END IF;

    RETURN jsonb_build_object(
        'queue_created', output_queue_created,
        'fsm_name', input_fsm_name,
        'fsm_version', input_fsm_version,
        'fsm_instance_id', fsm_instance_id,
        'fsm_instance_context', instance_context,
        'send_event_result', send_event_result,
        'message', output_message,
        'extra_message', output_extra_message
    );
END;
$$;



--
-- Name: tx_now(); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."tx_now"() RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE
    AS $$
  select case
    when nullif(current_setting('fsm_core.sim_now', true), '') is null then now()
    when pg_has_role(session_user, 'fsm_sim', 'MEMBER')
      then current_setting('fsm_core.sim_now', true)::timestamptz
    else now()
  end;
$$;



--
-- Name: fsm_instance; Type: TABLE; Schema: fsm_core; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "fsm_core"."fsm_instance" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "fsm_name" "text",
    "fsm_version" "text",
    "fsm_type" "text",
    "fsm_instance_context" "jsonb",
    "fsm_instance_state" "jsonb",
    "fsm_instance_status" "jsonb",
    "fsm_instance_output" "jsonb",
    "fsm_instance_error" "jsonb",
    "fsm_instance_xstate_state" "jsonb",
    "total_schedule_queue_data" "jsonb" DEFAULT '[]'::"jsonb",
    "parent_fsm_instance_id" "uuid",
    "childrens" "jsonb",
    "started_at" timestamp with time zone DEFAULT "fsm_core"."tx_now"(),
    "ended_at" timestamp with time zone,
    "worker_lock_expires_at" timestamp with time zone,
    "worker_locked" boolean DEFAULT false,
    "worker_locked_at" timestamp with time zone,
    "worker_locked_by" "text",
    "total_async_operation_queue_data" "jsonb" DEFAULT '[]'::"jsonb",
    "parent_invoke_id" "text",
    "internal_event_queue" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "internal_event_count" integer DEFAULT 0 NOT NULL
);



--
-- Name: COLUMN "fsm_instance"."parent_fsm_instance_id"; Type: COMMENT; Schema: fsm_core; Owner: postgres
--

COMMENT ON COLUMN "fsm_core"."fsm_instance"."parent_fsm_instance_id" IS 'The fsm_instance that invoked this one as a child FSM; NULL when started by the API, pgfsmctl or the system. When this instance finishes, that parent is sent xstate.done.actor.<parent_invoke_id> (done) or xstate.error.actor.<parent_invoke_id> (error).';


--
-- Name: COLUMN "fsm_instance"."parent_invoke_id"; Type: COMMENT; Schema: fsm_core; Owner: postgres
--

COMMENT ON COLUMN "fsm_core"."fsm_instance"."parent_invoke_id" IS 'The parent''s invoke id for this child (XState''s child actor id), which names the events the parent gets when this instance finishes.';


--
-- Name: COLUMN "fsm_instance"."internal_event_queue"; Type: COMMENT; Schema: fsm_core; Owner: postgres
--

COMMENT ON COLUMN "fsm_core"."fsm_instance"."internal_event_queue" IS 'Events raised by the instance''s own microsteps (xstate.done.state.<id>), oldest first. The sync worker takes the head before reading the instance''s pgmq queue; the archive appends to it and removes the head in the same transaction as the state. Cleared when the instance stops being active.';


--
-- Name: COLUMN "fsm_instance"."internal_event_count"; Type: COMMENT; Schema: fsm_core; Owner: postgres
--

COMMENT ON COLUMN "fsm_core"."fsm_instance"."internal_event_count" IS 'Internal events processed since the last event from the pgmq queue. Past 100 the instance is set to error (an infinite loop).';


--
-- Name: discard_fsm_macrostep_v2("fsm_core"."fsm_instance", "text", bigint, "jsonb", "jsonb"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."discard_fsm_macrostep_v2"("input_instance_row" "fsm_core"."fsm_instance", "input_reason" "text", "input_processed_queue_msg_id" bigint, "input_processed_internal_event" "jsonb", "input_processed_message" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    INSERT INTO fsm_core.fsm_instance_queue_event_logs (
        fsm_instance_id, fsm_instance_id_fsm_type, fsm_instance_id_fsm_version,
        fsm_instance_queue_msg_id, event_name, event_data, event_source, event_status
    ) VALUES (
        input_instance_row.id, input_instance_row.fsm_type, input_instance_row.fsm_version,
        input_processed_queue_msg_id,
        COALESCE(
            input_processed_internal_event->>'eventType',
            input_processed_message->'eventData'->>'eventType',
            'macrostep'
        ),
        jsonb_build_object(
            'reason', input_reason,
            'processed_internal_event', input_processed_internal_event,
            'source', input_processed_message->'source'
        ),
        CASE WHEN input_processed_internal_event IS NULL THEN 'queue' ELSE 'internal' END,
        'discarded'
    );
    RETURN jsonb_build_object(
        'discarded', true,
        'discarded_reason', input_reason,
        'fsm_instance_status', input_instance_row.fsm_instance_status,
        'internal_event_queue', COALESCE(input_instance_row.internal_event_queue, '[]'::jsonb),
        'internal_event_count', input_instance_row.internal_event_count
    );
END;
$$;



--
-- Name: enqueue_fsm_dispatch_v1("text", "text", "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."enqueue_fsm_dispatch_v1"("input_instance_id" "text", "input_fsm_name" "text", "input_fsm_version" "text", "input_dispatch_type" "text" DEFAULT 'start'::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  dispatch_queue_exists boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM pgmq.list_queues() WHERE queue_name = 'master_worker_dispatch_queue_start'
  ) INTO dispatch_queue_exists;

  IF NOT dispatch_queue_exists THEN
    PERFORM pgmq.create(queue_name := 'master_worker_dispatch_queue_start');
  END IF;

  PERFORM pgmq.send(
    queue_name := 'master_worker_dispatch_queue_start',
    msg        := jsonb_build_object(
      'id',          input_instance_id,
      'fsm_name',    input_fsm_name,
      'fsm_version', input_fsm_version
    )
  );
END;
$$;



--
-- Name: enqueue_fsm_dispatch_v2("uuid", "text", "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."enqueue_fsm_dispatch_v2"("input_instance_id" "uuid", "input_fsm_name" "text", "input_fsm_version" "text", "input_dispatch_type" "text" DEFAULT 'start'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO fsm_core.fsm_instance_and_fsm_workerlet (fsm_instance_id, fsm_name, fsm_version, dispatch_type)
  VALUES (input_instance_id, input_fsm_name, input_fsm_version, input_dispatch_type);

  PERFORM pg_notify('fsm_scheduler_work', input_instance_id::text);
END;
$$;



--
-- Name: ensure_async_operation_queue_for_worker_v2("text", "text", "text", "text", "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."ensure_async_operation_queue_for_worker_v2"("input_parent_fsm_name" "text", "input_parent_fsm_version" "text", "input_async_operation_type" "text", "input_async_operation_name" "text", "input_async_operation_version" "text", "input_async_operation_language" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    computed_queue_name text;
    already_existed boolean;
BEGIN
    computed_queue_name := fsm_core.compute_async_operation_queue_name_v2(
        input_parent_fsm_name, input_parent_fsm_version, input_async_operation_type,
        input_async_operation_name, input_async_operation_version, input_async_operation_language
    );

    SELECT EXISTS (
        SELECT 1 FROM pgmq.meta WHERE queue_name = computed_queue_name
    ) INTO already_existed;

    IF NOT already_existed THEN
        PERFORM pgmq.create(computed_queue_name);
    END IF;

    RETURN jsonb_build_object(
        'queue_name', computed_queue_name,
        'already_existed', already_existed
    );
END;
$$;



--
-- Name: enter_states_v2("fsm_core"."fsm_transitions", "text"[], boolean, "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."enter_states_v2"("transition_record" "fsm_core"."fsm_transitions", "state_node_set" "text"[], "is_initial" boolean, "fsm_name_param" "text", "fsm_version_param" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
-- XState's enterStates (packages/core/src/stateUtils.ts) for one transition:
--
--   computeEntrySet(filteredTransitions, historyValue, statesForDefaultEntry, statesToEnter);
--   if (isInitial) statesForDefaultEntry.add(snapshot.machine.root);
--   const completedNodes = new Set();
--   for (const stateNodeToEnter of [...statesToEnter].sort((a, b) => a.order - b.order)) {
--     mutStateNodeSet.add(stateNodeToEnter);
--     actions.push(...stateNodeToEnter.entry, spawnChild per invoke,
--                  ...initial.actions if statesForDefaultEntry.has(stateNodeToEnter));
--     if (stateNodeToEnter.type === 'final') {
--       const parent = stateNodeToEnter.parent;
--       let ancestorMarker = parent?.type === 'parallel' ? parent : parent?.parent;
--       if (parent?.type === 'compound') {
--         internalQueue.push(createDoneStateEvent(parent!.id, ...output));
--       }
--       while (ancestorMarker?.type === 'parallel' && !completedNodes.has(ancestorMarker)
--              && isInFinalState(mutStateNodeSet, ancestorMarker)) {
--         completedNodes.add(ancestorMarker);
--         internalQueue.push(createDoneStateEvent(ancestorMarker.id));
--         ancestorMarker = ancestorMarker.parent;
--       }
--       if (ancestorMarker) continue;
--       nextSnapshot = cloneMachineSnapshot(nextSnapshot, { status: 'done', ... });
--     }
--   }
--
-- compute_entry_set_v2 is computeEntrySet. The loop goes through the states to
-- enter as XState's does: adds each to the active states, collects its actions
-- and, for a final state, raises its done.state events and decides done
-- (SPEC-010, #518). Each state is added before its check, so when two regions
-- finish in one microstep their parallel state is done only at the second, and
-- raises once. The actions are returned for the sync worker to run: a state's
-- entry actions and a spawnChild per invoke in entry_actions, its initial
-- actions in initial_actions (the worker puts each after its state's entry
-- actions, orderEntryActions).
--
-- state_node_set is the active states after exitStates (exit_states_v2).
-- Returns states_to_enter, entry_actions, initial_actions, state_node_set
-- (mutStateNodeSet afterwards, sorted), raised_events
-- ([{eventType: xstate.done.state.<state id>}], without a final state's
-- output, a function that isn't in fsm.json) and done (a final state was
-- entered and no enclosing state is left to finish: the machine itself is
-- done).
DECLARE
    entry_set JSONB;
    states_to_enter TEXT[];
    states_for_default_entry TEXT[];
    entry_actions JSONB := '[]'::jsonb;
    initial_actions JSONB := '[]'::jsonb;
    mut_state_node_set TEXT[] := COALESCE(state_node_set, ARRAY[]::TEXT[]);
    completed_nodes TEXT[] := ARRAY[]::TEXT[];
    raised_events JSONB := '[]'::jsonb;
    is_done BOOLEAN := FALSE;
    state_to_enter fsm_core.fsm_states;
    parent fsm_core.fsm_states;
    ancestor_marker fsm_core.fsm_states;
    has_parent BOOLEAN;
    has_ancestor_marker BOOLEAN;
BEGIN
    -- computeEntrySet(filteredTransitions, historyValue, statesForDefaultEntry, statesToEnter);
    -- if (isInitial) statesForDefaultEntry.add(snapshot.machine.root): on the
    -- initial step compute_entry_set_v2 already counts the root as one.
    entry_set := fsm_core.compute_entry_set_v2(
        transition_record := transition_record,
        fsm_name_param := fsm_name_param,
        fsm_version_param := fsm_version_param,
        is_initial_transition := is_initial
    );
    states_to_enter := ARRAY(SELECT jsonb_array_elements_text(COALESCE(entry_set->'states_to_enter', '[]'::jsonb)));
    states_for_default_entry := ARRAY(SELECT jsonb_array_elements_text(COALESCE(entry_set->'states_for_default_entry', '[]'::jsonb)));

    -- [...statesToEnter].sort((a, b) => a.order - b.order)
    FOR state_to_enter IN
        SELECT * FROM fsm_core.fsm_states fs
        WHERE fs.fsm_name = fsm_name_param
          AND fs.fsm_version = fsm_version_param
          AND fs.computed_state_key_ltree::TEXT = ANY(states_to_enter)
        ORDER BY fs.fsm_order ASC
    LOOP
        -- mutStateNodeSet.add(stateNodeToEnter)
        IF NOT (state_to_enter.computed_state_key_ltree::TEXT = ANY(mut_state_node_set)) THEN
            mut_state_node_set := array_append(mut_state_node_set, state_to_enter.computed_state_key_ltree::TEXT);
        END IF;

        -- actions.push(...stateNodeToEnter.entry), and a spawnChild per invoke
        entry_actions := entry_actions || fsm_core.get_entry_actions_v2(
            input_state_paths := ARRAY[state_to_enter.computed_state_key_ltree::TEXT],
            input_fsm_name := fsm_name_param,
            input_fsm_version := fsm_version_param
        );
        -- if (statesForDefaultEntry.has(stateNodeToEnter)) actions.push(...initial.actions)
        IF state_to_enter.computed_state_key_ltree::TEXT = ANY(states_for_default_entry) THEN
            initial_actions := initial_actions || fsm_core.get_initial_actions_v2(
                input_state_paths := ARRAY[state_to_enter.computed_state_key_ltree::TEXT],
                input_fsm_name := fsm_name_param,
                input_fsm_version := fsm_version_param
            );
        END IF;

        -- if (stateNodeToEnter.type === 'final')
        CONTINUE WHEN state_to_enter.type <> 'final';

        -- const parent = stateNodeToEnter.parent;
        SELECT * INTO parent FROM fsm_core.fsm_states fs
        WHERE fs.fsm_name = fsm_name_param
          AND fs.fsm_version = fsm_version_param
          AND fs.computed_state_key_ltree::TEXT = state_to_enter.parent_node;
        has_parent := FOUND;

        -- let ancestorMarker = parent?.type === 'parallel' ? parent : parent?.parent;
        has_ancestor_marker := FALSE;
        IF has_parent AND parent.type = 'parallel' THEN
            ancestor_marker := parent;
            has_ancestor_marker := TRUE;
        ELSIF has_parent THEN
            SELECT * INTO ancestor_marker FROM fsm_core.fsm_states fs
            WHERE fs.fsm_name = fsm_name_param
              AND fs.fsm_version = fsm_version_param
              AND fs.computed_state_key_ltree::TEXT = parent.parent_node;
            has_ancestor_marker := FOUND;
        END IF;

        -- if (parent?.type === 'compound') internalQueue.push(createDoneStateEvent(parent.id))
        IF has_parent AND parent.type = 'compound' THEN
            raised_events := raised_events || jsonb_build_array(jsonb_build_object('eventType', 'xstate.done.state.' || parent.id));
        END IF;

        -- while (ancestorMarker?.type === 'parallel' && !completedNodes.has(ancestorMarker)
        --        && isInFinalState(mutStateNodeSet, ancestorMarker))
        WHILE has_ancestor_marker
            AND ancestor_marker.type = 'parallel'
            AND NOT (ancestor_marker.computed_state_key_ltree::TEXT = ANY(completed_nodes))
            AND fsm_core.is_in_final_state_v2(mut_state_node_set, ancestor_marker.computed_state_key_ltree::TEXT, fsm_name_param, fsm_version_param)
        LOOP
            completed_nodes := array_append(completed_nodes, ancestor_marker.computed_state_key_ltree::TEXT);
            raised_events := raised_events || jsonb_build_array(jsonb_build_object('eventType', 'xstate.done.state.' || ancestor_marker.id));
            -- ancestorMarker = ancestorMarker.parent
            SELECT * INTO ancestor_marker FROM fsm_core.fsm_states fs
            WHERE fs.fsm_name = fsm_name_param
              AND fs.fsm_version = fsm_version_param
              AND fs.computed_state_key_ltree::TEXT = ancestor_marker.parent_node;
            has_ancestor_marker := FOUND;
        END LOOP;

        -- if (ancestorMarker) continue; otherwise the machine is done.
        CONTINUE WHEN has_ancestor_marker;
        is_done := TRUE;
    END LOOP;

    RETURN jsonb_build_object(
        'states_to_enter', to_jsonb(states_to_enter),
        'entry_actions', entry_actions,
        'initial_actions', initial_actions,
        'state_node_set', to_jsonb(ARRAY(
            SELECT DISTINCT x FROM unnest(mut_state_node_set || states_to_enter) AS x ORDER BY x
        )),
        'raised_events', raised_events,
        'done', is_done
    );
END;
$$;



--
-- Name: exit_states_v2("fsm_core"."fsm_transitions", "text"[], "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."exit_states_v2"("transition_record" "fsm_core"."fsm_transitions", "state_node_set" "text"[], "fsm_name_param" "text", "fsm_version_param" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
-- XState's exitStates (packages/core/src/stateUtils.ts) for one transition:
--
--   const statesToExit = computeExitSet(transitions, mutStateNodeSet, historyValue);
--   statesToExit.sort((a, b) => b.order - a.order);
--   // (record history for each exited state's history children)
--   for (const s of statesToExit) {
--     ... [...s.exit, ...s.invoke.map((def) => stopChild(def.id))] ...
--     mutStateNodeSet.delete(s);
--   }
--
-- Returns exit_nodes (statesToExit), exit_actions in that order, and
-- state_node_set (mutStateNodeSet after the exits), which microstep_v2 passes
-- to enter_states_v2. History states are not supported, so nothing is
-- recorded for them.
DECLARE
    exit_nodes TEXT[];
    exit_actions JSONB;
    remaining_state_nodes TEXT[];
BEGIN
    -- No transition: nothing exits.
    IF transition_record IS NULL THEN
        RETURN jsonb_build_object(
            'exit_nodes', '[]'::jsonb,
            'exit_actions', '[]'::jsonb,
            'state_node_set', to_jsonb(COALESCE(state_node_set, ARRAY[]::TEXT[]))
        );
    END IF;

    -- const statesToExit = computeExitSet(transitions, mutStateNodeSet, historyValue);
    exit_nodes := COALESCE(
        fsm_core.compute_full_exit_set_v2(transition_record := transition_record, state_node_set := state_node_set),
        ARRAY[]::TEXT[]
    );

    -- statesToExit.sort((a, b) => b.order - a.order), then per state its exit
    -- actions and a stopChild per invoke: get_exit_actions_v2 returns them in
    -- that order (fsm_order DESC, exit before invoke).
    exit_actions := fsm_core.get_exit_actions_v2(
        input_state_paths := exit_nodes,
        input_fsm_name := fsm_name_param,
        input_fsm_version := fsm_version_param
    )->'actions';

    -- mutStateNodeSet.delete(s), for each state exited
    remaining_state_nodes := ARRAY(
        SELECT s FROM unnest(COALESCE(state_node_set, ARRAY[]::TEXT[])) AS s
        WHERE NOT (s = ANY(exit_nodes))
    );

    RETURN jsonb_build_object(
        'exit_nodes', to_jsonb(exit_nodes),
        'exit_actions', COALESCE(exit_actions, '[]'::jsonb),
        'state_node_set', to_jsonb(remaining_state_nodes)
    );
END;
$$;



--
-- Name: find_least_common_ancestor_v2("public"."ltree"[], "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."find_least_common_ancestor_v2"("input_paths" "public"."ltree"[], "input_fsm_name" "text", "input_fsm_version" "text") RETURNS "public"."ltree"
    LANGUAGE "sql" STABLE
    AS $$
    -- Where ltree's lca() would do: it already returns a proper ancestor
    -- (lca('r.c.x', 'r.c') = 'r', never one of its inputs), so with the root's
    -- key path as an extra input (input_root) this needs no table:
    --
    --   SELECT CASE WHEN lca(input_paths) <@ input_root THEN lca(input_paths) END;
    --
    -- That form is only for a pure function (IMMUTABLE, not reading
    -- fsm_core.fsm_states): it takes the root path as an input instead of
    -- looking anything up.
    -- `<@ input_root` rejects a result above the root ('' or 'com.acme' for
    -- the root "com.acme.m"). Or, without the root input, keep lca() only
    -- when it is a state, which rejects those same results:
    --
    --   SELECT fs.computed_state_key_ltree
    --   FROM fsm_core.fsm_states fs
    --   WHERE fs.fsm_name = input_fsm_name
    --     AND fs.fsm_version = input_fsm_version
    --     AND fs.computed_state_key_ltree = lca(input_paths);
    --
    -- Both are only right while no state key has a dot: lca('k.p.s3.1',
    -- 'k.p.s3.2') = 'k.p.s3', which is no state (their parent is k.p). The
    -- first returns that non-state; the second returns NULL, so the domain
    -- falls back to the root, too high. Searching the states below gives k.p.
    SELECT fs.computed_state_key_ltree
    FROM fsm_core.fsm_states fs
    WHERE fs.fsm_name = input_fsm_name
      AND fs.fsm_version = input_fsm_version
      AND fs.computed_state_key_ltree @> ALL (input_paths)       -- contains every path
      AND NOT (fs.computed_state_key_ltree = ANY (input_paths))  -- but is none of them
    ORDER BY nlevel(fs.computed_state_key_ltree) DESC            -- the deepest one
    LIMIT 1;
$$;



--
-- Name: finish_async_operation_event_v2("text", "text", bigint, "text", "text", "text", "text", "jsonb", integer, "uuid", "text", timestamp with time zone, integer, timestamp with time zone, "text", "jsonb", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."finish_async_operation_event_v2"("input_archive_reason" "text", "input_async_operation_queue_name" "text", "input_async_operation_queue_msg_id" bigint, "input_async_operation_queue_type" "text" DEFAULT NULL::"text", "input_async_operation_queue_version" "text" DEFAULT NULL::"text", "input_event_name" "text" DEFAULT NULL::"text", "input_event_action_type" "text" DEFAULT NULL::"text", "input_event_data" "jsonb" DEFAULT NULL::"jsonb", "input_event_delay" integer DEFAULT 0, "input_send_to_parent_queue_id" "uuid" DEFAULT NULL::"uuid", "input_send_to_parent_queue_id_event_name" "text" DEFAULT NULL::"text", "input_execution_started_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "input_execution_duration" integer DEFAULT NULL::integer, "input_execution_finished_at" timestamp with time zone DEFAULT "fsm_core"."tx_now"(), "input_event_status" "text" DEFAULT NULL::"text", "input_event_output" "jsonb" DEFAULT NULL::"jsonb", "input_error_message" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    archived boolean;
    send_to_parent_result jsonb;
    cancel_notified boolean := false;
    logged_status text;
    logged_event_name text;
    logged_event_data jsonb;
    output_async_operation_queue_event_log_id uuid;
BEGIN
    IF input_archive_reason IS NULL OR input_archive_reason NOT IN ('completed', 'cancelled') THEN
        RAISE EXCEPTION 'finish_async_operation_event_v2: the archive reason must be completed or cancelled, not %', input_archive_reason;
    END IF;

    -- 1. The gate: only the call that archives the message acts on it.
    archived := pgmq.archive(
        queue_name := input_async_operation_queue_name,
        msg_id := input_async_operation_queue_msg_id
    );

    IF input_archive_reason = 'completed' THEN
        logged_event_name := input_event_name;
        IF NOT archived THEN
            -- Cancelled (its state exited), or finished already: nobody
            -- waits for this result.
            send_to_parent_result := jsonb_build_object('skipped', true, 'reason', 'message already archived');
        ELSIF input_send_to_parent_queue_id IS NOT NULL
            AND input_send_to_parent_queue_id <> fsm_core.pg_system_queue_uuid()
            AND input_send_to_parent_queue_id <> fsm_core.api_system_queue_uuid()
        THEN
            -- 2. A real parent: send it the result, with its source. (No
            --    parent, or a system sentinel: there is nobody to tell.)
            send_to_parent_result := fsm_core.send_event_to_fsm_queue_with_event_logs_v2(
                input_fsm_instance_id := input_send_to_parent_queue_id,
                input_fsm_instance_id_fsm_type := NULL,
                input_fsm_instance_id_fsm_version := NULL,
                input_event_name := input_event_name,
                input_event_action_type := 'async_operation_completed',
                input_event_data := input_event_output,
                input_event_delay := 0,
                input_event_status := input_event_status,
                input_event_output := input_event_output,
                input_error_message := input_error_message,
                input_execution_started_at := input_execution_started_at,
                input_execution_duration := input_execution_duration,
                input_execution_finished_at := input_execution_finished_at,
                input_event_source := jsonb_build_object(
                    'invoke_id', input_send_to_parent_queue_id_event_name,
                    'queue_id', input_async_operation_queue_name,
                    'queue_msg_id', input_async_operation_queue_msg_id
                )
            );
        ELSE
            send_to_parent_result := jsonb_build_object('skipped', true, 'reason', 'no real parent to notify');
        END IF;
        logged_status := CASE WHEN archived THEN input_event_status ELSE 'discarded' END;
        logged_event_data := CASE WHEN archived THEN input_event_data
            ELSE jsonb_build_object('archive_reason', input_archive_reason, 'reason', 'message already archived', 'event_data', input_event_data)
        END;
    ELSE
        logged_event_name := 'cancel';
        IF archived THEN
            -- 2. The invoking state exited while its message was still on the
            --    queue, waiting or being run by a worker: announce it.
            PERFORM pg_notify(
                'fsm_async_operation_cancel',
                jsonb_build_object(
                    'queue_name', input_async_operation_queue_name,
                    'msg_id', input_async_operation_queue_msg_id
                )::text
            );
            cancel_notified := true;
            logged_status := 'canceled';
        ELSE
            -- Its result was archived first: the worker has finished, and
            -- there is nothing to cancel.
            logged_status := 'discarded';
            logged_event_data := jsonb_build_object('archive_reason', input_archive_reason, 'reason', 'message already archived');
        END IF;
    END IF;

    -- 3. Log it.
    INSERT INTO fsm_core.fsm_async_operation_queue_event_logs (
        async_operation_queue_name,
        async_operation_queue_type,
        async_operation_queue_version,
        async_operation_queue_msg_id,
        event_name,
        event_data,
        event_delay,
        send_to_parent_queue_id,
        send_to_parent_queue_id_event_name,
        execution_started_at,
        execution_duration,
        execution_finished_at,
        event_status,
        event_output,
        error_message
    ) VALUES (
        input_async_operation_queue_name,
        input_async_operation_queue_type,
        input_async_operation_queue_version,
        input_async_operation_queue_msg_id,
        logged_event_name,
        logged_event_data,
        input_event_delay,
        input_send_to_parent_queue_id,
        input_send_to_parent_queue_id_event_name,
        input_execution_started_at,
        input_execution_duration,
        input_execution_finished_at,
        logged_status,
        input_event_output,
        input_error_message
    ) RETURNING async_operation_queue_event_log_id INTO output_async_operation_queue_event_log_id;

    -- 4. The result. The old functions' keys are kept, so their callers read
    --    the same fields: async_operation_queue_archive_result,
    --    send_to_parent_result (completion), archive_result, queue_msg_id
    --    (cancel).
    RETURN jsonb_build_object(
        'archive_reason', input_archive_reason,
        'archive_result', archived,
        'async_operation_queue_archive_result', archived,
        'status', logged_status,
        'async_operation_queue_name', input_async_operation_queue_name,
        'async_operation_queue_msg_id', input_async_operation_queue_msg_id,
        'queue_msg_id', input_async_operation_queue_msg_id,
        'send_to_parent_result', send_to_parent_result,
        'cancel_notified', cancel_notified,
        'async_operation_queue_event_log_id', output_async_operation_queue_event_log_id
    );
END;
$$;



--
-- Name: fsm_get_all_state_nodes_v1("text"[], "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."fsm_get_all_state_nodes_v1"("p_state_paths" "text"[], "p_fsm_name" "text", "p_fsm_version" "text") RETURNS "text"[]
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    node_rec RECORD;
    child_rec RECORD;
    resultNodeset text[] := ARRAY[]::text[];
    initialStates text[];
    initialStateNode text;
    log_text TEXT := '';
    child_log TEXT;
    all_fsm_states fsm_core.fsm_states[];
    temp_flag BOOLEAN;
BEGIN
    RAISE NOTICE '[fsm_core.fsm_get_all_state_nodes_v1] Input state_paths: %', p_state_paths;
    
    SELECT array_agg(fsm_states ORDER BY fsm_order ASC) INTO all_fsm_states
    FROM fsm_core.fsm_states
    WHERE fsm_name = p_fsm_name AND fsm_version = p_fsm_version AND computed_state_key_ltree::text = ANY(p_state_paths);

    RAISE NOTICE '[fsm_core.fsm_get_all_state_nodes_v1] Matching fsm_core.fsm_states count: %', array_length(all_fsm_states, 1);

    FOR node_rec IN
        SELECT * FROM unnest(all_fsm_states) AS fsm_states
    LOOP
        log_text := log_text || format(E'\nProcessing node: %s (type=%s)', node_rec.computed_state_key_ltree, node_rec.type);
        RAISE NOTICE 'Processing node: % (type=%)', node_rec.computed_state_key_ltree, node_rec.type;
        IF node_rec.type = 'compound' THEN

            
            -- Check if node_rec.computed_state_key_ltree is immediate parent of any node in p_state_paths
            -- iterate through p_state_paths and check if any path has node_rec.computed_state_key_ltree as prefix (immediate parent)
            
            temp_flag := true;

            FOR child_rec IN SELECT * FROM unnest(all_fsm_states) AS fsm_states LOOP

                RAISE NOTICE 'Checking if node % is immediate parent of path %', node_rec.computed_state_key_ltree, child_rec.computed_state_key_ltree;
                IF node_rec.computed_state_key_ltree::text = child_rec.parent_node::text THEN
                    RAISE NOTICE 'Node % is immediate parent of path % so skipping its initial states...', node_rec.computed_state_key_ltree, child_rec.computed_state_key_ltree;
                    temp_flag := FALSE;
                    EXIT; -- No need to check further
                END IF;
            END LOOP;


            IF temp_flag THEN
                RAISE NOTICE 'Compound node % is not immediate parent of any path, adding initial states with ancestors...', node_rec.computed_state_key_ltree;
                initialStates := fsm_core.fsm_get_initial_state_nodes_with_ancestors_v1(p_fsm_name := p_fsm_name, p_fsm_version := p_fsm_version, p_state_path := node_rec.computed_state_key_ltree::ltree);
               
                RAISE NOTICE 'Initial states with ancestors for node %: %', node_rec.computed_state_key_ltree, initialStates;
                IF initialStates IS NOT NULL THEN
                    FOREACH initialStateNode IN ARRAY initialStates LOOP
                        IF initialStateNode IS NOT NULL AND NOT (initialStateNode = ANY(resultNodeset)) THEN
                            resultNodeset := array_append(resultNodeset, initialStateNode);
                            RAISE NOTICE 'Added initialStateNode: %', initialStateNode;
                           
                        END IF;
                    END LOOP;
                END IF;
            END IF;    
        ELSIF node_rec.type = 'parallel' THEN
            
            RAISE NOTICE 'Parallel node % found, iterating children...', node_rec.computed_state_key_ltree;
            IF node_rec.states IS NOT NULL THEN
                FOR child_rec IN SELECT value FROM jsonb_each(node_rec.states) LOOP
                    RAISE NOTICE 'Processing child node in parallel state: %', child_rec.value->>'id';
                    
                    initialStates := fsm_core.fsm_get_initial_state_nodes_with_ancestors_v1(p_fsm_name := p_fsm_name, p_fsm_version := p_fsm_version, p_state_path := fsm_core.sanitize_text_to_ltree(input_text := child_rec.value->>'id'));
                    RAISE NOTICE 'Initial states with ancestors for child node %: %', child_rec.value->>'id', initialStates;
                    
                    IF initialStates IS NOT NULL THEN
                        FOREACH initialStateNode IN ARRAY initialStates LOOP
                            IF initialStateNode IS NOT NULL AND NOT (initialStateNode = ANY(resultNodeset)) THEN
                                resultNodeset := array_append(resultNodeset, initialStateNode);
                                RAISE NOTICE 'Added child initialStateNode: %', initialStateNode;
                            END IF;
                        END LOOP;
                    END IF;
                END LOOP;
            END IF;
        ELSEIF node_rec.type = 'atomic' THEN
            
            RAISE NOTICE 'Atomic node % found, adding to resultNodeset...', node_rec.computed_state_key_ltree;
            resultNodeset := array_append(resultNodeset, node_rec.computed_state_key_ltree::text);
            
            RAISE NOTICE 'Added atomic node: %', node_rec.computed_state_key_ltree::text;
        ELSE
            log_text := log_text || E'\n  Node type is final/history or unknown, skipping it.';
            
        
        END IF;
    END LOOP;

   
    RAISE NOTICE '[fsm_core.fsm_get_all_state_nodes_v1] Log:%', log_text;
    RAISE NOTICE '[fsm_core.fsm_get_all_state_nodes_v1] ResultNodeset: %', resultNodeset;
    RETURN COALESCE(resultNodeset, ARRAY[]::text[]);
END;
$$;



--
-- Name: fsm_get_all_state_nodes_v2("text"[], "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."fsm_get_all_state_nodes_v2"("input_state_paths" "text"[], "input_fsm_name" "text", "input_fsm_version" "text") RETURNS "text"[]
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    node_rec RECORD;
    child_rec RECORD;
    resultNodeset text[] := ARRAY[]::text[];
    initialStates text[];
    initialStateNode text;
    log_text TEXT := '';
    child_log TEXT;
    all_fsm_states fsm_core.fsm_states[];
    temp_flag BOOLEAN;
    active_node text;
    ancestor text;
BEGIN
    RAISE NOTICE '[fsm_core.fsm_get_all_state_nodes_v2] Input state_paths: %', input_state_paths;
    
    SELECT array_agg(fsm_states ORDER BY fsm_order ASC) INTO all_fsm_states
    FROM fsm_core.fsm_states
    WHERE fsm_name = input_fsm_name AND fsm_version = input_fsm_version AND computed_state_key_ltree::text = ANY(input_state_paths);

    RAISE NOTICE '[fsm_core.fsm_get_all_state_nodes_v2] Matching fsm_core.fsm_states count: %', array_length(all_fsm_states, 1);

    FOR node_rec IN
        SELECT * FROM unnest(all_fsm_states) AS fsm_states
    LOOP
        log_text := log_text || format(E'\nProcessing node: %s (type=%s)', node_rec.computed_state_key_ltree, node_rec.type);
        RAISE NOTICE 'Processing node: % (type=%)', node_rec.computed_state_key_ltree, node_rec.type;
        IF node_rec.type = 'compound' THEN

            
            -- Check if node_rec.computed_state_key_ltree is immediate parent of any node in input_state_paths
            -- iterate through input_state_paths and check if any path has node_rec.computed_state_key_ltree as prefix (immediate parent)
            
            temp_flag := true;

            FOR child_rec IN SELECT * FROM unnest(all_fsm_states) AS fsm_states LOOP

                RAISE NOTICE 'Checking if node % is immediate parent of path %', node_rec.computed_state_key_ltree, child_rec.computed_state_key_ltree;
                IF node_rec.computed_state_key_ltree::text = child_rec.parent_node::text THEN
                    RAISE NOTICE 'Node % is immediate parent of path % so skipping its initial states...', node_rec.computed_state_key_ltree, child_rec.computed_state_key_ltree;
                    temp_flag := FALSE;
                    EXIT; -- No need to check further
                END IF;
            END LOOP;


            IF temp_flag THEN
                RAISE NOTICE 'Compound node % is not immediate parent of any path, adding initial states with ancestors...', node_rec.computed_state_key_ltree;
                initialStates := fsm_core.fsm_get_initial_state_nodes_with_ancestors_v2(input_fsm_name := input_fsm_name, input_fsm_version := input_fsm_version, input_state_path := node_rec.computed_state_key_ltree::ltree);
               
                RAISE NOTICE 'Initial states with ancestors for node %: %', node_rec.computed_state_key_ltree, initialStates;
                IF initialStates IS NOT NULL THEN
                    FOREACH initialStateNode IN ARRAY initialStates LOOP
                        IF initialStateNode IS NOT NULL AND NOT (initialStateNode = ANY(resultNodeset)) THEN
                            resultNodeset := array_append(resultNodeset, initialStateNode);
                            RAISE NOTICE 'Added initialStateNode: %', initialStateNode;
                           
                        END IF;
                    END LOOP;
                END IF;
            END IF;    
        ELSIF node_rec.type = 'parallel' THEN
            
            RAISE NOTICE 'Parallel node % found, iterating children...', node_rec.computed_state_key_ltree;
            -- Regions are this FSM version's child rows, by key path like every
            -- other path here: a child's `id` (in `states`) is only its key path
            -- when it has no custom id. History children are not regions.
            FOR child_rec IN
                SELECT fs.computed_state_key_ltree::text AS path
                FROM fsm_core.fsm_states fs
                WHERE fs.fsm_name = input_fsm_name
                  AND fs.fsm_version = input_fsm_version
                  AND fs.parent_node = node_rec.computed_state_key_ltree::text
                  AND fs.type <> 'history'
                ORDER BY fs.fsm_order
            LOOP
                -- A region in the saved state keeps its own states (it is a node of
                -- its own here); only a region missing from it starts at its
                -- initial state. Adding every region's initial chain reset parallel
                -- states on every step (#503).
                CONTINUE WHEN child_rec.path = ANY(input_state_paths);
                RAISE NOTICE 'Processing child node in parallel state: %', child_rec.path;

                initialStates := fsm_core.fsm_get_initial_state_nodes_with_ancestors_v2(input_fsm_name := input_fsm_name, input_fsm_version := input_fsm_version, input_state_path := child_rec.path::ltree);
                RAISE NOTICE 'Initial states with ancestors for child node %: %', child_rec.path, initialStates;

                IF initialStates IS NOT NULL THEN
                    FOREACH initialStateNode IN ARRAY initialStates LOOP
                        IF initialStateNode IS NOT NULL AND NOT (initialStateNode = ANY(resultNodeset)) THEN
                            resultNodeset := array_append(resultNodeset, initialStateNode);
                            RAISE NOTICE 'Added child initialStateNode: %', initialStateNode;
                        END IF;
                    END LOOP;
                END IF;
            END LOOP;
        -- A final state is an active leaf too; skipping it dropped every
        -- region that had finished (#503).
        ELSEIF node_rec.type IN ('atomic', 'final') THEN
            
            RAISE NOTICE 'Atomic node % found, adding to resultNodeset...', node_rec.computed_state_key_ltree;
            resultNodeset := array_append(resultNodeset, node_rec.computed_state_key_ltree::text);
            
            RAISE NOTICE 'Added atomic node: %', node_rec.computed_state_key_ltree::text;
        ELSE
            log_text := log_text || E'\n  Node type is final/history or unknown, skipping it.';
            
        
        END IF;
    END LOOP;

   
    RAISE NOTICE '[fsm_core.fsm_get_all_state_nodes_v2] Log:%', log_text;
    RAISE NOTICE '[fsm_core.fsm_get_all_state_nodes_v2] ResultNodeset: %', resultNodeset;
    -- An active node's ancestors are active too (XState's configuration), so
    -- a transition defined on a compound or parallel state (its onDone, or an
    -- event it handles) matches. Without them only leaves could (#503).
    FOREACH active_node IN ARRAY COALESCE(resultNodeset, ARRAY[]::text[]) LOOP
        FOR i IN 1 .. nlevel(active_node::ltree) - 1 LOOP
            ancestor := subpath(active_node::ltree, 0, i)::text;
            IF NOT (ancestor = ANY(resultNodeset)) THEN
                resultNodeset := array_append(resultNodeset, ancestor);
            END IF;
        END LOOP;
    END LOOP;

    RETURN COALESCE(resultNodeset, ARRAY[]::text[]);
END;
$$;



--
-- Name: fsm_get_initial_state_nodes_v1("text", "text", "public"."ltree"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."fsm_get_initial_state_nodes_v1"("p_fsm_name" "text", "p_fsm_version" "text", "p_state_path" "public"."ltree") RETURNS "text"[]
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    results text[];
BEGIN
    WITH RECURSIVE traverse(node_path) AS (
        -- Base case
        SELECT p_state_path

        UNION ALL

        -- Recursive step: handle compound and parallel in one recursive query
        SELECT
            CASE
                WHEN s.type = 'compound'
                     AND s.initial->'target'->>0 IS NOT NULL
                THEN fsm_core.sanitize_text_to_ltree(input_text := s.initial->'target'->>0)::ltree

                WHEN s.type = 'parallel'
                     AND s.states IS NOT NULL
                THEN (t.node_path::text || '.' || fsm_core.sanitize_text_to_ltree(input_text := c.value->>'key')::text)::ltree

                ELSE NULL
            END AS next_path
        FROM traverse t
        JOIN fsm_core.fsm_states s
          ON s.computed_state_key_ltree = t.node_path
         AND s.fsm_name = p_fsm_name
         AND s.fsm_version = p_fsm_version
        LEFT JOIN LATERAL jsonb_each(s.states) c
          ON s.type = 'parallel'
        WHERE (s.type = 'compound' AND s.initial->'target'->>0 IS NOT NULL)
           OR (s.type = 'parallel' AND s.states IS NOT NULL)
    )
    SELECT array_agg(DISTINCT node_path::text)
    INTO results
    FROM traverse
    WHERE node_path IS NOT NULL;

    RETURN results;
END;
$$;



