-- Name: fsm_get_initial_state_nodes_v2("text", "text", "public"."ltree"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."fsm_get_initial_state_nodes_v2"("input_fsm_name" "text", "input_fsm_version" "text", "input_state_path" "public"."ltree") RETURNS "text"[]
    LANGUAGE "plpgsql"
