CREATE OR REPLACE FUNCTION "fsm_core"."fsm_get_initial_state_nodes_with_ancestors_v2"("input_fsm_name" "text", "input_fsm_version" "text", "input_state_path" "public"."ltree") RETURNS "text"[]
