--
-- Name: get_proper_ancestors("text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."get_proper_ancestors"("state_path_ltree" "text", "to_state_path_ltree" "text") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
    ancestors TEXT[] := ARRAY[]::TEXT[];
    current_path ltree;
    to_path ltree;
    parent_path ltree;
BEGIN
    -- Convert input to ltree
    current_path := state_path_ltree::ltree;
    to_path := to_state_path_ltree::ltree;

    -- If both are equal, return empty array
    IF current_path = to_path THEN
        RETURN ancestors;
    END IF;

    -- Walk up the tree, collecting parents, until to_path or root
    parent_path := subpath(current_path, 0, nlevel(current_path) - 1);

    WHILE nlevel(parent_path) > 0 AND parent_path <> to_path LOOP
        ancestors := array_append(ancestors, parent_path::TEXT);
        parent_path := subpath(parent_path, 0, nlevel(parent_path) - 1);
    END LOOP;

    RETURN ancestors;
END;
$$;



--
-- Name: get_proper_ancestors_ltree("public"."ltree", "public"."ltree"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."get_proper_ancestors_ltree"("state_path_ltree" "public"."ltree", "to_state_path_ltree" "public"."ltree") RETURNS "public"."ltree"[]
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
    ancestors ltree[] := ARRAY[]::ltree[];
    parent_path ltree;
BEGIN
    -- If both are equal, return empty array
    IF state_path_ltree = to_state_path_ltree THEN
        RETURN ancestors;
    END IF;

    -- Start from the immediate parent
    parent_path := subpath(state_path_ltree, 0, nlevel(state_path_ltree) - 1);

    WHILE nlevel(parent_path) > 0 AND parent_path <> to_state_path_ltree LOOP
        ancestors := array_append(ancestors, parent_path);
        parent_path := subpath(parent_path, 0, nlevel(parent_path) - 1);
    END LOOP;

    RETURN ancestors;
END;
$$;



--
-- Name: get_transition_domain_v2("public"."ltree", "public"."ltree"[], boolean, "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."get_transition_domain_v2"("input_source" "public"."ltree", "input_targets" "public"."ltree"[], "input_reenter" boolean, "input_fsm_name" "text", "input_fsm_version" "text") RETURNS "public"."ltree"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    targets ltree[] := COALESCE(input_targets, ARRAY[]::ltree[]);
    domain_path ltree;
BEGIN
    -- if (!transition.reenter && targetStates.every((target) =>
    --     target === transition.source || isDescendant(target, transition.source)))
    --   return transition.source;
    IF NOT COALESCE(input_reenter, false) AND NOT EXISTS (
        SELECT 1 FROM unnest(targets) AS t(p)
        WHERE NOT (t.p = input_source
                   OR fsm_core.is_descendant(input_child := t.p, input_parent := input_source))
    ) THEN
        RETURN input_source;
    END IF;

    -- const lca = findLeastCommonAncestor(targetStates.concat(transition.source));
    -- if (lca) return lca;
    domain_path := fsm_core.find_least_common_ancestor_v2(
        input_paths := targets || input_source,
        input_fsm_name := input_fsm_name,
        input_fsm_version := input_fsm_version
    );
    IF domain_path IS NOT NULL THEN
        RETURN domain_path;
    END IF;

    -- No proper ancestor: the source or a target is the root.
    -- if (transition.reenter) return;   (no domain)
    IF COALESCE(input_reenter, false) THEN
        RETURN NULL;
    END IF;

    -- return transition.source.machine.root;
    SELECT fs.computed_state_key_ltree INTO domain_path
    FROM fsm_core.fsm_states fs
    WHERE fs.fsm_name = input_fsm_name
      AND fs.fsm_version = input_fsm_version
      AND fs.parent_node IS NULL;
    RETURN domain_path;
END;
$$;



