--
-- Name: register_scheduler_job_v2("text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."register_scheduler_job_v2"("input_schedule" "text" DEFAULT '5 seconds'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if exists (select 1 from cron.job where jobname = 'fsm_schedule_all_pending') then
    perform cron.unschedule('fsm_schedule_all_pending');
  end if;
  perform cron.schedule(
    'fsm_schedule_all_pending',
    input_schedule,
    'SELECT fsm_core.schedule_all_pending();'
  );
  return fsm_core.scheduler_job_status_v2();
end;
$$;



--
-- Name: remove_hashtag_from_text("text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."remove_hashtag_from_text"("input_text" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
    sanitized_text TEXT;
BEGIN
   

    -- Step 1: Remove unwanted characters (#, (), etc.)
    sanitized_text := REGEXP_REPLACE(sanitized_text, '[#]', '', 'g');

   
    -- Step 4: Handle empty string case
    IF sanitized_text = '' THEN
        RETURN NULL;
    END IF;

    RETURN sanitized_text;
END;
$$;



--
-- Name: require_version("text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."require_version"("input_expected" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
  found text;
begin
  begin
    found := fsm_core.version();
  exception when undefined_function then
    found := null;
  end;
  if found is distinct from input_expected then
    raise exception 'fsm_core % required, found %', input_expected,
      coalesce(found, 'a version before 2.3.0 (no fsm_core.version())')
      using hint = 'Apply the upgrade scripts in order, starting from the installed version.';
  end if;
end;
$$;



--
-- Name: resolve_state_value_v1("jsonb", "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."resolve_state_value_v1"("input_json" "jsonb", "input_fsm_name" "text", "input_fsm_version" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    root_node text;
    all_paths TEXT[];
    all_nodes TEXT[];
    nested_json JSONB;
    result_json JSONB;
    all_fsm_states fsm_core.fsm_states[];
    root_node_record fsm_core.fsm_states;
BEGIN
    -- Get root node for fsm_name and fsm_version (lowest fsm_order)
    -- SELECT computed_state_key_ltree INTO root_node
    -- FROM fsm_core.fsm_states
    -- WHERE fsm_name = input_fsm_name AND fsm_version = input_fsm_version
    -- ORDER BY fsm_order ASC
    -- LIMIT 1;

    -- RAISE NOTICE 'Root node: %', root_node;

    SELECT array_agg(fsm_states ORDER BY fsm_order ASC) INTO all_fsm_states
    FROM fsm_core.fsm_states
    WHERE fsm_name = input_fsm_name AND fsm_version = input_fsm_version;

    root_node_record := all_fsm_states[1]; -- Get the first record (lowest fsm_order) 
    
    root_node := root_node_record.computed_state_key_ltree::text; -- Extract the computed_state_key_ltree as text

    RAISE NOTICE 'Root node: %', root_node;

    -- Get all paths from the JSONB object, using root_node as prefix if found
    IF root_node IS NOT NULL THEN
        RAISE NOTICE 'Using root_node as prefix for jsonb_all_paths';
        all_paths := fsm_core.jsonb_all_paths(j := input_json, prefix := root_node);
    ELSE
        all_paths := fsm_core.jsonb_all_paths(j := input_json, prefix := '');
    END IF;

    RAISE NOTICE 'All paths: %', all_paths;
    -- Get all state nodes for these paths
    all_nodes := fsm_core.fsm_get_all_state_nodes_v1(p_state_paths := all_paths, p_fsm_name := input_fsm_name, p_fsm_version := input_fsm_version);

    RAISE NOTICE 'All nodes after fsm_core.fsm_get_all_state_nodes_v1: %', all_nodes;
    -- Build nested JSON from the state nodes
    nested_json := fsm_core.build_nested_json_recursive(paths := all_nodes);

    RAISE NOTICE 'Nested JSON: %', nested_json;

    -- Build a result object that contains both the nested JSON and the list of all nodes
    result_json := jsonb_build_object(
        'json', COALESCE(nested_json, '{}'::jsonb),
        'all_nodes', COALESCE(to_jsonb(all_nodes), '[]'::jsonb)
    );

    RAISE NOTICE 'Result JSON (json + all_nodes): %', result_json;

    RETURN result_json;
END;
$$;



--
-- Name: resolve_state_value_v2("jsonb", "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."resolve_state_value_v2"("input_json" "jsonb", "input_fsm_name" "text", "input_fsm_version" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    root_node text;
    all_paths TEXT[];
    all_nodes TEXT[];
    nested_json JSONB;
    result_json JSONB;
    all_fsm_states fsm_core.fsm_states[];
    root_node_record fsm_core.fsm_states;
BEGIN
    -- Get root node for fsm_name and fsm_version (lowest fsm_order)
    -- SELECT computed_state_key_ltree INTO root_node
    -- FROM fsm_core.fsm_states
    -- WHERE fsm_name = input_fsm_name AND fsm_version = input_fsm_version
    -- ORDER BY fsm_order ASC
    -- LIMIT 1;

    -- RAISE NOTICE 'Root node: %', root_node;

    SELECT array_agg(fsm_states ORDER BY fsm_order ASC) INTO all_fsm_states
    FROM fsm_core.fsm_states
    WHERE fsm_name = input_fsm_name AND fsm_version = input_fsm_version;

    root_node_record := all_fsm_states[1]; -- Get the first record (lowest fsm_order) 
    
    root_node := root_node_record.computed_state_key_ltree::text; -- Extract the computed_state_key_ltree as text

    RAISE NOTICE 'Root node: %', root_node;

    -- Get all paths from the JSONB object, using root_node as prefix if found
    IF root_node IS NOT NULL THEN
        RAISE NOTICE 'Using root_node as prefix for jsonb_all_paths';
        all_paths := fsm_core.jsonb_all_paths(j := input_json, prefix := root_node);
    ELSE
        all_paths := fsm_core.jsonb_all_paths(j := input_json, prefix := '');
    END IF;

    RAISE NOTICE 'All paths: %', all_paths;
    -- Get all state nodes for these paths
    all_nodes := fsm_core.fsm_get_all_state_nodes_v2(input_state_paths := all_paths, input_fsm_name := input_fsm_name, input_fsm_version := input_fsm_version);

    RAISE NOTICE 'All nodes after fsm_core.fsm_get_all_state_nodes_v2: %', all_nodes;
    -- Build nested JSON from the state nodes
    nested_json := fsm_core.build_nested_json_recursive(paths := all_nodes);

    RAISE NOTICE 'Nested JSON: %', nested_json;

    -- Build a result object that contains both the nested JSON and the list of all nodes
    result_json := jsonb_build_object(
        'json', COALESCE(nested_json, '{}'::jsonb),
        'all_nodes', COALESCE(to_jsonb(all_nodes), '[]'::jsonb)
    );

    RAISE NOTICE 'Result JSON (json + all_nodes): %', result_json;

    RETURN result_json;
END;
$$;



--
-- Name: resume_event_for_fsm_worker_v2("uuid"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."resume_event_for_fsm_worker_v2"("input_fsm_instance_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_fsm_name    text;
    v_fsm_version text;
BEGIN
    SELECT fsm_name, fsm_version
    INTO v_fsm_name, v_fsm_version
    FROM fsm_core.fsm_instance
    WHERE id = input_fsm_instance_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'status',          'fsm_not_found',
            'fsm_instance_id', input_fsm_instance_id
        );
    END IF;

    PERFORM fsm_core.enqueue_fsm_dispatch_v2(
        input_fsm_instance_id,
        v_fsm_name,
        v_fsm_version,
        'resume'
    );

    RETURN jsonb_build_object(
        'status',          'queued',
        'fsm_instance_id', input_fsm_instance_id,
        'fsm_name',        v_fsm_name,
        'fsm_version',     v_fsm_version
    );
END;
$$;



--
-- Name: revoke_api_key("text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."revoke_api_key"("input_id_or_name" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pg_temp'
    AS $$
DECLARE
  v_count int;
BEGIN
  UPDATE fsm_core.api_keys
  SET revoked_at = fsm_core.tx_now()
  WHERE revoked_at IS NULL
    AND (id::text = input_id_or_name OR name = input_id_or_name);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count > 0;
END;
$$;



--
-- Name: sanitize_text_array_to_ltree_array("text"[]); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."sanitize_text_array_to_ltree_array"("input_array" "text"[]) RETURNS "public"."ltree"[]
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
    result LTREE[];
    element TEXT;
    sanitized_ltree LTREE;
BEGIN
    result := ARRAY[]::LTREE[];
    
    -- Handle NULL input
    IF input_array IS NULL THEN
        RETURN result;
    END IF;
    
    -- Process each element in the array using fsm_core.sanitize_text_to_ltree
    FOREACH element IN ARRAY input_array
    LOOP
        sanitized_ltree := fsm_core.sanitize_text_to_ltree(input_text := element);
        
        -- Add to result if sanitization was successful
        IF sanitized_ltree IS NOT NULL THEN
            result := array_append(result, sanitized_ltree);
        END IF;
    END LOOP;
    
    RETURN result;
-- EXCEPTION
--     WHEN OTHERS THEN
--         -- If any conversion fails, return empty array
--         RETURN ARRAY[]::LTREE[];
END;
$$;



--
-- Name: sanitize_text_array_to_ltree_text_array("text"[]); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."sanitize_text_array_to_ltree_text_array"("input_array" "text"[]) RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
    result TEXT[];
    element TEXT;
    sanitized_ltree LTREE;
BEGIN
    result := ARRAY[]::TEXT[];
    
    -- Handle NULL input
    IF input_array IS NULL THEN
        RETURN result;
    END IF;
    
    -- Process each element in the array using fsm_core.sanitize_text_to_ltree
    FOREACH element IN ARRAY input_array
    LOOP
        sanitized_ltree := fsm_core.sanitize_text_to_ltree(input_text := element);
        
        -- Add to result if sanitization was successful
        IF sanitized_ltree IS NOT NULL THEN
            result := array_append(result, sanitized_ltree::TEXT);
        END IF;
    END LOOP;
    
    RETURN result;
-- EXCEPTION
--     WHEN OTHERS THEN
--         -- If any conversion fails, return empty array
--         RETURN ARRAY[]::LTREE[];
END;
$$;



--
-- Name: sanitize_text_to_ltree("text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."sanitize_text_to_ltree"("input_text" "text") RETURNS "public"."ltree"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
    sanitized_text TEXT;
BEGIN
    -- Step 1: Replace whitespace with underscores
    sanitized_text := REGEXP_REPLACE(COALESCE(input_text, ''), '\s+', '_', 'g');

    -- Step 2: Remove unwanted characters (#, (), etc.)
    sanitized_text := REGEXP_REPLACE(sanitized_text, '[#()]', '', 'g');

    -- Step 3: Remove any characters not allowed in ltree (keep letters, numbers, _, ., -)
    sanitized_text := REGEXP_REPLACE(sanitized_text, '[^a-zA-Z0-9_.-]', '', 'g');

    -- Step 4: Handle empty string case
    IF sanitized_text = '' THEN
        RETURN NULL;
    END IF;

    RETURN sanitized_text::ltree;
END;
$$;



--
-- Name: schedule_all_pending(integer); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."schedule_all_pending"("input_stale_threshold_seconds" integer DEFAULT 30) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  WHILE fsm_core.schedule_next_pending(input_stale_threshold_seconds) LOOP
    NULL;
  END LOOP;
END;
$$;



--
-- Name: schedule_next_pending(integer); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."schedule_next_pending"("input_stale_threshold_seconds" integer DEFAULT 30) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_entry_id          uuid;
  v_instance_id       uuid;
  v_fsm_name          text;
  v_fsm_version       text;
  v_chosen_fsmlet_id  uuid;
BEGIN
  -- Step 1: claim the oldest pending entry (SKIP LOCKED = safe for parallel schedulers).
  SELECT fsm_instance_and_fsm_workerlet_id, fsm_instance_id, fsm_name, fsm_version
  INTO v_entry_id, v_instance_id, v_fsm_name, v_fsm_version
  FROM fsm_core.fsm_instance_and_fsm_workerlet
  WHERE status = 'pending'
  ORDER BY created_at
  FOR UPDATE SKIP LOCKED
  LIMIT 1;

  IF v_entry_id IS NULL THEN
    RETURN false;
  END IF;

  -- Step 2: pick the best available fsmlet.
  --   Filter: heartbeat within threshold (node is alive)
  --           AND fsm_modules contains this fsm_name+version
  --           AND active_workers < max_concurrency (has a free slot)
  --   Score:  most available slots first (max_concurrency - active_workers DESC)
  SELECT fsm_workerlet_id
  INTO v_chosen_fsmlet_id
  FROM fsm_core.fsm_workerlet
  WHERE
    last_heartbeat > fsm_core.tx_now() - (input_stale_threshold_seconds || ' seconds')::interval
    AND active_workers < max_concurrency
    AND fsm_modules @> jsonb_build_array(
          jsonb_build_object('fsm_name', v_fsm_name, 'fsm_version', v_fsm_version)
        )
  ORDER BY (max_concurrency - active_workers) DESC
  LIMIT 1;

  IF v_chosen_fsmlet_id IS NULL THEN
    -- No capable fsmlet right now — leave status=pending, retry on next cycle.
    RETURN false;
  END IF;

  -- Step 3: assign the entry to the chosen fsmlet.
  UPDATE fsm_core.fsm_instance_and_fsm_workerlet
  SET
    status              = 'scheduled',
    fsm_workerlet_id = v_chosen_fsmlet_id,
    scheduled_at        = fsm_core.tx_now()
  WHERE fsm_instance_and_fsm_workerlet_id = v_entry_id;

  -- Step 4: wake the fsmlet via pg_notify.
  PERFORM pg_notify('fsm_fsmlet_work_' || v_chosen_fsmlet_id::text, v_instance_id::text);

  RETURN true;
END;
$$;



--
-- Name: scheduler_job_status_v2(); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."scheduler_job_status_v2"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
declare
  job record;
begin
  select jobid, schedule, command, active
    into job
    from cron.job
   where jobname = 'fsm_schedule_all_pending';
  if not found then
    return jsonb_build_object('jobname', 'fsm_schedule_all_pending', 'registered', false);
  end if;
  return jsonb_build_object(
    'jobname', 'fsm_schedule_all_pending',
    'registered', true,
    'jobid', job.jobid,
    'schedule', job.schedule,
    'command', job.command,
    'active', job.active
  );
end;
$$;



--
-- Name: select_all_transitions_v1("text", "text"[], "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."select_all_transitions_v1"("event_name" "text", "p_state_value" "text"[], "fsm_name_param" "text", "fsm_version_param" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
	transitions JSONB;
BEGIN
	transitions := (
		SELECT jsonb_agg(t)
		FROM (
			SELECT * FROM fsm_core.fsm_transitions
			WHERE event_type = event_name
			  AND computed_sanitized_source_ltree::text = ANY(p_state_value)
			  AND fsm_name = fsm_name_param
			  AND fsm_version = fsm_version_param
		) t
	);
	IF transitions IS NULL THEN
		transitions := '[]'::jsonb;
	END IF;
	RETURN transitions;
END;
$$;



--
-- Name: select_all_transitions_v2("text", "text"[], "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."select_all_transitions_v2"("event_name" "text", "input_state_value" "text"[], "fsm_name_param" "text", "fsm_version_param" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
	transitions JSONB;
BEGIN
	transitions := (
		-- In definition order: the loader inserts a state's transitions in
		-- document order, and selection takes the first whose guard passes
		-- (XState's StateNode.next, #510).
		SELECT jsonb_agg(t ORDER BY t.id)
		FROM (
			SELECT * FROM fsm_core.fsm_transitions
			WHERE event_type = event_name
			  AND computed_sanitized_source_ltree::text = ANY(input_state_value)
			  AND fsm_name = fsm_name_param
			  AND fsm_version = fsm_version_param
		) t
	);
	IF transitions IS NULL THEN
		transitions := '[]'::jsonb;
	END IF;
	RETURN transitions;
END;
$$;



--
-- Name: select_transitions_with_guard_eval_v1("fsm_core"."fsm_transitions"[]); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."select_transitions_with_guard_eval_v1"("input_all_transitions" "fsm_core"."fsm_transitions"[]) RETURNS SETOF "fsm_core"."fsm_transitions"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
	transition_record fsm_core.fsm_transitions;
	guard_value BOOLEAN;
BEGIN

	RAISE NOTICE 'fsm_core.select_transitions_with_guard_eval_v1 called with input_all_transitions: %', input_all_transitions;
	FOR transition_record IN SELECT * FROM unnest(input_all_transitions) LOOP
		-- Default guard to TRUE when no cond provided
		guard_value := TRUE;

		IF transition_record.cond IS NOT NULL THEN
			RAISE NOTICE 'Evaluating guard condition and guard condition value: %', transition_record.cond;
			-- If cond has a 'type' field, call the named SQL function and pass cond->>'param' as JSONB
			IF transition_record.cond ? 'type' THEN
				RAISE NOTICE 'Calling guard function: % with param: %', transition_record.cond->>'type', transition_record.cond->>'param';

				EXECUTE 'SELECT ' || quote_ident(transition_record.cond->>'type') || '($1)'
				INTO guard_value
				USING (transition_record.cond->>'param')::JSONB;
				RAISE NOTICE 'Guard function result: %', guard_value;
			ELSE
				RAISE NOTICE 'Evaluating guard condition without function and guard condition value: %', transition_record.cond;
				-- Try common shapes: check for 'value' or 'predicate' keys, else if cond is boolean JSONB
				IF transition_record.cond ? 'value' THEN
					guard_value := COALESCE((transition_record.cond->>'value')::BOOLEAN, TRUE);
				-- ELSIF transition_record.cond ? 'predicate' THEN
				-- 	guard_value := COALESCE((transition_record.cond->>'predicate')::BOOLEAN, TRUE);
				ELSIF jsonb_typeof(transition_record.cond) = 'boolean' THEN
					-- cond is a bare boolean JSON value (true/false)
					guard_value := (transition_record.cond::TEXT)::BOOLEAN;
					RAISE NOTICE 'Guard boolean value: %', guard_value;
				ELSE
					-- Unknown cond structure: default to TRUE to avoid dropping transitions unexpectedly
					guard_value := TRUE;
					RAISE NOTICE 'Unknown guard condition structure, defaulting to TRUE';
				END IF;
			END IF;
		END IF;

		-- If guard evaluates to true, yield the transition record
		IF guard_value THEN
			RAISE NOTICE 'Guard condition passed, returning transition: %', transition_record;
			RETURN NEXT transition_record;
		END IF;
	END LOOP;

	RETURN;
END;
$_$;



