-- Name: select_transitions_with_guard_eval_v2("fsm_core"."fsm_transitions"[]); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."select_transitions_with_guard_eval_v2"("input_all_transitions" "fsm_core"."fsm_transitions"[]) RETURNS SETOF "fsm_core"."fsm_transitions"
