--
-- Name: send_event_to_async_operation_queue_with_event_logs_v2("text", "text", "text", "text", "uuid", "text", "text", "text", "text", "jsonb", integer, "text", "jsonb", "text", timestamp with time zone, integer, timestamp with time zone); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."send_event_to_async_operation_queue_with_event_logs_v2"("input_async_operation_queue_name" "text", "input_async_operation_fn_name" "text", "input_async_operation_queue_type" "text", "input_async_operation_queue_version" "text", "input_send_to_parent_queue_id" "uuid", "input_send_to_parent_queue_type" "text", "input_send_to_parent_queue_id_event_name" "text", "input_event_name" "text", "input_event_action_type" "text", "input_event_data" "jsonb", "input_event_delay" integer DEFAULT 0, "input_event_status" "text" DEFAULT 'ACTIVE'::"text", "input_event_output" "jsonb" DEFAULT '{}'::"jsonb", "input_error_message" "text" DEFAULT NULL::"text", "input_execution_started_at" timestamp with time zone DEFAULT "fsm_core"."tx_now"(), "input_execution_duration" integer DEFAULT NULL::integer, "input_execution_finished_at" timestamp with time zone DEFAULT "fsm_core"."tx_now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    queue_msg_data jsonb;
    output_async_operation_queue_msg_id bigint;
    output_async_operation_queue_event_log_id uuid;
BEGIN
    IF input_async_operation_queue_name IS NULL THEN
        RAISE EXCEPTION 'async_operation_queue_name is NULL';
    END IF;

    queue_msg_data := jsonb_build_object(
        'eventData', jsonb_build_object(
            'eventType',    input_event_name,
            'eventPayload', input_event_data,
            'actionType',   input_event_action_type
        ),
        'queueId',                    input_async_operation_queue_name,
        'queueFnName',                input_async_operation_fn_name,
        'queueType',                  input_async_operation_queue_type,
        'queueVersion',               input_async_operation_queue_version,
        'sendToParentQueueId',        input_send_to_parent_queue_id,
        'sendToParentQueueType',      input_send_to_parent_queue_type,
        'sendToParentQueueIdEventName', input_send_to_parent_queue_id_event_name
    );

    BEGIN
        SELECT pgmq.send(queue_name := input_async_operation_queue_name, msg := queue_msg_data, delay := input_event_delay)
        INTO output_async_operation_queue_msg_id;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'pgmq.send failed for queue %: %', input_async_operation_queue_name, SQLERRM;
    END;

    IF output_async_operation_queue_msg_id IS NULL THEN
        RAISE EXCEPTION 'Failed to send event to queue %', input_async_operation_queue_name;
    END IF;

    -- Append queueMsgId to queue_msg_data
    queue_msg_data := queue_msg_data || jsonb_build_object('queueMsgId', output_async_operation_queue_msg_id);

    -- Append queueMsgDelay to queue_msg_data
    queue_msg_data := queue_msg_data || jsonb_build_object('queueMsgDelay', input_event_delay);


    INSERT INTO fsm_core.fsm_async_operation_queue_event_logs (
        async_operation_queue_name,
        async_operation_fn_name,
        async_operation_queue_type,
        async_operation_queue_version,
        async_operation_queue_msg_id,
        event_name,
        event_data,
        event_delay,
        send_to_parent_queue_id,
        send_to_parent_queue_id_event_name,
        execution_started_at,
        execution_duration,
        execution_finished_at,
        event_status,
        event_output,
        error_message
    ) VALUES (
        input_async_operation_queue_name,
        input_async_operation_fn_name,
        input_async_operation_queue_type,
        input_async_operation_queue_version,
        output_async_operation_queue_msg_id,
        input_event_name,
        input_event_data,
        input_event_delay,
        input_send_to_parent_queue_id,
        input_send_to_parent_queue_id_event_name,
        input_execution_started_at,
        input_execution_duration,
        input_execution_finished_at,
        input_event_status,
        input_event_output,
        input_error_message
    ) RETURNING async_operation_queue_event_log_id INTO output_async_operation_queue_event_log_id;


    RETURN jsonb_build_object(
        'queue_data', queue_msg_data,
        -- 'queue_msg_id', output_async_operation_queue_msg_id,
        -- 'queue_msg_delay', input_event_delay,
        'queue_event_log_id', output_async_operation_queue_event_log_id,
        'event_status', input_event_status,
        'event_output', input_event_output,
        'error_message', input_error_message
    );
END;
$$;



--
-- Name: send_event_to_fsm_queue_with_event_logs_v2("uuid", "text", "text", "text", "text", "jsonb", integer, "text", "jsonb", "text", timestamp with time zone, integer, timestamp with time zone, "jsonb"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."send_event_to_fsm_queue_with_event_logs_v2"("input_fsm_instance_id" "uuid", "input_fsm_instance_id_fsm_type" "text", "input_fsm_instance_id_fsm_version" "text", "input_event_name" "text", "input_event_action_type" "text", "input_event_data" "jsonb", "input_event_delay" integer DEFAULT 0, "input_event_status" "text" DEFAULT 'ACTIVE'::"text", "input_event_output" "jsonb" DEFAULT '{}'::"jsonb", "input_error_message" "text" DEFAULT NULL::"text", "input_execution_started_at" timestamp with time zone DEFAULT "fsm_core"."tx_now"(), "input_execution_duration" integer DEFAULT NULL::integer, "input_execution_finished_at" timestamp with time zone DEFAULT "fsm_core"."tx_now"(), "input_event_source" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    queue_msg_data jsonb;
    output_fsm_instance_queue_msg_id bigint;
    output_fsm_instance_queue_event_log_id uuid;
BEGIN
    IF input_fsm_instance_id IS NULL THEN
        RAISE EXCEPTION 'fsm_instance_id is NULL';
    END IF;

    queue_msg_data := jsonb_build_object(
        'eventData', jsonb_build_object(
            'eventType',    input_event_name,
            'eventPayload', input_event_data,
            'actionType',   input_event_action_type
        ),
        'queueId',                    input_fsm_instance_id,
        'queueType',                  input_fsm_instance_id_fsm_type,
        'queueVersion',               input_fsm_instance_id_fsm_version
        -- No reply-to (sendToParent*) on an FSM queue's messages: nothing reads
        -- it; a child FSM's parent is on its fsm_instance row (#523, #526).
    );

    IF input_event_source IS NOT NULL THEN
        queue_msg_data := queue_msg_data || jsonb_build_object('source', input_event_source);
    END IF;

    BEGIN
        SELECT pgmq.send(queue_name := input_fsm_instance_id::text, msg := queue_msg_data, delay := input_event_delay)
        INTO output_fsm_instance_queue_msg_id;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'pgmq.send failed for queue %: %', input_fsm_instance_id, SQLERRM;
    END;

    IF output_fsm_instance_queue_msg_id IS NULL THEN
        RAISE EXCEPTION 'Failed to send event to queue %', input_fsm_instance_id;
    END IF;

    -- Append queueMsgId to queue_msg_data
    queue_msg_data := queue_msg_data || jsonb_build_object('queueMsgId', output_fsm_instance_queue_msg_id);

    -- Append queueMsgDelay to queue_msg_data
    queue_msg_data := queue_msg_data || jsonb_build_object('queueMsgDelay', input_event_delay);

    INSERT INTO fsm_core.fsm_instance_queue_event_logs (
        fsm_instance_id,
        fsm_instance_id_fsm_type,
        fsm_instance_id_fsm_version,
        fsm_instance_queue_msg_id,
        event_name,
        event_data,
        event_delay,
        execution_started_at,
        execution_duration,
        execution_finished_at,
        event_status,
        event_output,
        error_message
    ) VALUES (
        input_fsm_instance_id,
        input_fsm_instance_id_fsm_type,
        input_fsm_instance_id_fsm_version,
        output_fsm_instance_queue_msg_id,
        input_event_name,
        input_event_data,
        input_event_delay,
        input_execution_started_at,
        input_execution_duration,
        input_execution_finished_at,
        input_event_status,
        input_event_output,
        input_error_message
    ) RETURNING fsm_instance_queue_event_log_id INTO output_fsm_instance_queue_event_log_id;

    RETURN jsonb_build_object(
        'queue_data', queue_msg_data,
        'queue_event_log_id', output_fsm_instance_queue_event_log_id,
        'event_status', input_event_status,
        'event_output', input_event_output,
        'error_message', input_error_message
    );
END;
$$;



--
-- Name: sql_lca_for_transition("jsonb"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."sql_lca_for_transition"("transition" "jsonb") RETURNS "public"."ltree"
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    AS $$
DECLARE
  source TEXT;
  sanitized_source LTREE;
  sanitized_source_ltree LTREE;
  target_array TEXT[];
  sanitized_target_array LTREE[];
  sanitized_target_ltree_array LTREE[];
  transition_domain_lca LTREE;
BEGIN
  -- Clean source
  source := transition->>'source';
  sanitized_source := fsm_core.sanitize_text_to_ltree(source);
  SELECT computed_state_key_ltree INTO sanitized_source_ltree
  FROM fsm_states
  WHERE computed_state_id_ltree = sanitized_source;

  RAISE NOTICE 'sanitized_source_ltree: %', sanitized_source_ltree;
  IF sanitized_source_ltree IS NULL THEN
    RETURN NULL;
  END IF;

   SELECT ARRAY(
          SELECT jsonb_array_elements_text(transition->'target')
  ) INTO target_array;

  RAISE NOTICE 'target_array: %', target_array;
  -- Sanitize target array
  IF target_array IS NULL THEN
      sanitized_target_array := ARRAY[]::ltree[];
  ELSE
      sanitized_target_array := fsm_core.sanitize_text_array_to_ltree_array(target_array);
  END IF;


  SELECT ARRAY(
          SELECT computed_state_key_ltree
          FROM fsm_states
          WHERE computed_state_id_ltree = ANY(sanitized_target_array)
  ) INTO sanitized_target_ltree_array;

  RAISE NOTICE 'sanitized_target_array: %', sanitized_target_ltree_array;


  -- Use already sanitized target array in transition_domain_lca
  transition_domain_lca := fsm_core.sql_lca_from_array(
      ARRAY[sanitized_source_ltree::ltree] || sanitized_target_ltree_array
  );

  RAISE NOTICE 'transition_domain_lca: %', transition_domain_lca;
  -- If LCA calculation returned NULL, fall back to the root label of source (first path element)
  IF transition_domain_lca IS NULL THEN
    BEGIN
      -- subpath(...,0,1) returns the root/top-most label of the ltree
      transition_domain_lca := subpath(sanitized_source_ltree, 0, 1);
    EXCEPTION WHEN OTHERS THEN
      -- leave as NULL if source isn't a valid ltree
      RAISE NOTICE 'Error in fallback transition_domain_lca calculation: %', SQLERRM;
      transition_domain_lca := NULL;
    END;
  END IF;

  RETURN transition_domain_lca;
END;
$$;



--
-- Name: sql_lca_from_array("public"."ltree"[]); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."sql_lca_from_array"("paths" "public"."ltree"[]) RETURNS "public"."ltree"
    LANGUAGE "sql" IMMUTABLE STRICT
    AS $$
  SELECT ancestor
  FROM (
    SELECT subpath(paths[1], 0, i) AS ancestor, i
    FROM generate_series(1, nlevel(paths[1])) AS i
  ) AS candidates
  WHERE NOT EXISTS (
    SELECT 1
    FROM unnest(paths) AS input(p)
    WHERE NOT (candidates.ancestor @> input.p)
  )
  ORDER BY candidates.i DESC
  LIMIT 1;
$$;



--
-- Name: start_async_operation_for_worker_v2("text", "text", "jsonb", "text", "text", "text", "text", "uuid", "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."start_async_operation_for_worker_v2"("invoke_id" "text", "src" "text", "input" "jsonb", "action_type" "text", "async_operation_type" "text", "async_operation_version" "text", "async_operation_language" "text", "parent_fsm_instance_id" "uuid", "parent_fsm_name" "text", "parent_fsm_version" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    async_operation_queue_name text;
    send_result jsonb;
BEGIN
    IF async_operation_type NOT IN ('internalAsyncOperation', 'sharedAsyncOperation') THEN
        RAISE EXCEPTION 'start_async_operation_for_worker_v2: unsupported async operation type: %', async_operation_type;
    END IF;

    async_operation_queue_name := fsm_core.compute_async_operation_queue_name_v2(
        parent_fsm_name, parent_fsm_version, async_operation_type, src, async_operation_version, async_operation_language
    );

    IF NOT EXISTS (
        SELECT 1 FROM pgmq.list_queues() q WHERE q.queue_name = async_operation_queue_name
    ) THEN
        PERFORM pgmq.create(queue_name := async_operation_queue_name);
    END IF;

    -- The message keeps its reply-to: the gateway sends the operation's result
    -- to sendToParentQueueId as xstate.done.actor.<sendToParentQueueIdEventName>.
    send_result := fsm_core.send_event_to_async_operation_queue_with_event_logs_v2(
        input_async_operation_queue_name := async_operation_queue_name,
        input_async_operation_fn_name := src,
        input_async_operation_queue_type := async_operation_type,
        input_async_operation_queue_version := async_operation_version,
        input_send_to_parent_queue_id := parent_fsm_instance_id,
        input_send_to_parent_queue_type := 'FSM',
        input_send_to_parent_queue_id_event_name := invoke_id,
        input_event_name := invoke_id,
        input_event_action_type := action_type,
        input_event_data := input,
        input_event_delay := 0,
        input_event_status := 'async_operation_started',
        input_event_output := '{}'::jsonb,
        input_error_message := NULL
    );

    RETURN jsonb_build_object(
        'invoke_id', invoke_id,
        'src', src,
        'async_operation_type', async_operation_type,
        'queue_id', async_operation_queue_name,
        'queue_msg_id', send_result->'queue_data'->'queueMsgId',
        'queue_event_log_id', send_result->'queue_event_log_id',
        'queue_data', send_result->'queue_data'
    );
END;
$$;



--
-- Name: start_child_fsm_v2("text", "text", "jsonb", "text", "text", "uuid"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."start_child_fsm_v2"("invoke_id" "text", "src" "text", "input" "jsonb", "fsm_name" "text", "fsm_version" "text", "parent_fsm_instance_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
-- An invoked machine is a child actor in XState; here it is a real
-- fsm_instance, created like any other (its row, transition rows, dispatch to
-- an fsmlet, queue and initialTransition_event) with this instance recorded as
-- its parent and invoke_id as its invoke id, so the parent is told when it
-- finishes (archive step 9, #523). Before, only a queue was made: no row (the
-- event log's foreign key failed the parent's archive), no dispatch, and the
-- invoke id was sent as the child's first event.
DECLARE
    create_result jsonb;
BEGIN
    create_result := fsm_core.create_fsm_instance_from_name_v2(
        input_fsm_name := fsm_name,
        input_fsm_version := fsm_version,
        input_fsm_context := COALESCE(input, '{}'::jsonb),
        create_pgmq_queue := true,
        input_parent_fsm_instance_id := parent_fsm_instance_id,
        input_parent_invoke_id := invoke_id
    );
    IF NOT COALESCE((create_result->>'queue_created')::boolean, false) THEN
        RAISE EXCEPTION 'child FSM %@% (invoke %) was created without a queue: %',
            fsm_name, fsm_version, invoke_id, create_result->>'message';
    END IF;

    -- When the invoking state exits, the parent's archive stops the child,
    -- running or not, with stop_child_fsm_v2 (#534).
    RETURN jsonb_build_object(
        'invoke_id', invoke_id,
        'src', src,
        'async_operation_type', 'fsm',
        'queue_id', create_result->>'fsm_instance_id',
        'queue_msg_id', create_result->'send_event_result'->'queue_data'->'queueMsgId',
        'queue_event_log_id', create_result->'send_event_result'->'queue_event_log_id',
        'queue_data', create_result->'send_event_result'->'queue_data'
    );
END;
$$;



--
-- Name: start_invoked_async_operation_v2("text", "text", "jsonb", "text", "text", "text", "text", "uuid", "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."start_invoked_async_operation_v2"("invoke_id" "text", "src" "text", "input" "jsonb", "action_type" "text", "async_operation_type" "text", "async_operation_version" "text", "async_operation_language" "text", "parent_fsm_instance_id" "uuid", "parent_fsm_name" "text", "parent_fsm_version" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF async_operation_type IN ('internalAsyncOperation', 'sharedAsyncOperation') THEN
        RETURN fsm_core.start_async_operation_for_worker_v2(
            invoke_id := invoke_id,
            src := src,
            input := input,
            action_type := action_type,
            async_operation_type := async_operation_type,
            async_operation_version := async_operation_version,
            async_operation_language := async_operation_language,
            parent_fsm_instance_id := parent_fsm_instance_id,
            parent_fsm_name := parent_fsm_name,
            parent_fsm_version := parent_fsm_version
        );
    ELSIF async_operation_type = 'fsm' THEN
        -- A child FSM: a real instance with this one as its parent (#523).
        -- src names the child machine.
        RETURN fsm_core.start_child_fsm_v2(
            invoke_id := invoke_id,
            src := src,
            input := input,
            fsm_name := src,
            fsm_version := async_operation_version,
            parent_fsm_instance_id := parent_fsm_instance_id
        );
    ELSE
        RAISE EXCEPTION 'start_invoked_async_operation_v2: unsupported async operation type: %', async_operation_type;
    END IF;
END;
$$;



--
-- Name: stop_child_fsm_v2("uuid"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."stop_child_fsm_v2"("input_child_fsm_instance_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN fsm_core.stop_fsm_instance_v2(input_child_fsm_instance_id, 'stop_child');
END;
$$;



--
-- Name: stop_event_for_fsm_worker_v1("uuid"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."stop_event_for_fsm_worker_v1"("input_fsm_instance_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    instance_row  fsm_core.fsm_instance%ROWTYPE;
    unlock_result boolean;
    event_log_id  uuid;
BEGIN
    -- 1. Fetch instance row (carries worker lock columns)
    SELECT * INTO instance_row
    FROM fsm_core.fsm_instance
    WHERE id = input_fsm_instance_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'status',          'fsm_not_found',
            'fsm_instance_id', input_fsm_instance_id,
            'lock_record',     'null'::jsonb
        );
    END IF;

    -- 2. Worker is not running
    IF instance_row.worker_locked IS NOT TRUE THEN
        RETURN jsonb_build_object(
            'status',          'stopped_or_not_started',
            'fsm_instance_id', input_fsm_instance_id,
            'lock_record',     jsonb_build_object(
                'worker_locked',          instance_row.worker_locked,
                'worker_locked_by',       instance_row.worker_locked_by,
                'worker_locked_at',       instance_row.worker_locked_at,
                'worker_lock_expires_at', instance_row.worker_lock_expires_at
            )
        );
    END IF;

    -- 3. Unlock directly (avoids extra function-call round-trip)
    UPDATE fsm_core.fsm_instance
    SET
        worker_locked          = false,
        worker_locked_by       = NULL,
        worker_locked_at       = NULL,
        worker_lock_expires_at = NULL
    WHERE id = input_fsm_instance_id;
    unlock_result := FOUND;

    -- 4. pg_notify so the LISTEN connection wakes any live worker
    PERFORM pg_notify('fsm_worker_stop', input_fsm_instance_id::text);

    -- 5. Log to fsm_instance_queue_event_logs
    INSERT INTO fsm_core.fsm_instance_queue_event_logs (
        fsm_instance_id,
        event_name,
        event_status,
        event_data,
        execution_finished_at
    ) VALUES (
        input_fsm_instance_id,
        'stop_worker',
        'stopped',
        jsonb_build_object('triggered_by', 'stop_event_for_fsm_worker_v1'),
        fsm_core.tx_now()
    ) RETURNING fsm_instance_queue_event_log_id INTO event_log_id;

    -- 6. Return
    RETURN jsonb_build_object(
        'status',          'stopped',
        'fsm_instance_id', input_fsm_instance_id,
        'unlock_result',   unlock_result,
        'event_log_id',    event_log_id,
        'lock_record',     jsonb_build_object(
            'worker_locked',          instance_row.worker_locked,
            'worker_locked_by',       instance_row.worker_locked_by,
            'worker_locked_at',       instance_row.worker_locked_at,
            'worker_lock_expires_at', instance_row.worker_lock_expires_at
        )
    );
END;
$$;



--
-- Name: stop_event_for_fsm_worker_v2("uuid"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."stop_event_for_fsm_worker_v2"("input_fsm_instance_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    instance_row    fsm_core.fsm_instance%ROWTYPE;
    cancelled_count int;
    event_log_id    uuid;
BEGIN
    -- 1. Fetch instance row
    SELECT * INTO instance_row
    FROM fsm_core.fsm_instance
    WHERE id = input_fsm_instance_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'status',          'fsm_not_found',
            'fsm_instance_id', input_fsm_instance_id
        );
    END IF;

    -- 2. Guard: nothing to cancel if instance is in a terminal state
    --    (fsm_instance_status can be inspected here if needed in the future)

    -- 3. Cancel any pending or scheduled dispatch entry for this instance.
    DELETE FROM fsm_core.fsm_instance_and_fsm_workerlet
    WHERE fsm_instance_id = input_fsm_instance_id
      AND status IN ('pending', 'scheduled');
    GET DIAGNOSTICS cancelled_count = ROW_COUNT;

    -- 4. Log
    INSERT INTO fsm_core.fsm_instance_queue_event_logs (
        fsm_instance_id,
        event_name,
        event_status,
        event_data,
        execution_finished_at
    ) VALUES (
        input_fsm_instance_id,
        'stop_worker',
        'cancelled',
        jsonb_build_object(
            'triggered_by',    'stop_event_for_fsm_worker_v2',
            'cancelled_count', cancelled_count
        ),
        fsm_core.tx_now()
    ) RETURNING fsm_instance_queue_event_log_id INTO event_log_id;

    -- 5. Return
    RETURN jsonb_build_object(
        'status',          CASE WHEN cancelled_count > 0 THEN 'cancelled' ELSE 'not_queued' END,
        'fsm_instance_id', input_fsm_instance_id,
        'cancelled_count', cancelled_count,
        'event_log_id',    event_log_id
    );
END;
$$;



--
-- Name: stop_fsm_instance_v2("uuid", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."stop_fsm_instance_v2"("input_fsm_instance_id" "uuid", "input_event_name" "text" DEFAULT 'stop_fsm_instance'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    instance_row fsm_core.fsm_instance%ROWTYPE;
    cancelled_dispatch_count integer;
    archived_msg_ids bigint[];
    invoke_entry jsonb;
    stopped_invokes jsonb := '[]'::jsonb;
    event_log_id uuid;
BEGIN
    -- 1. Lock the instance. Already finished or stopped: nothing to do.
    SELECT * INTO instance_row
    FROM fsm_core.fsm_instance
    WHERE id = input_fsm_instance_id
    FOR NO KEY UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('status', 'fsm_not_found', 'fsm_instance_id', input_fsm_instance_id);
    END IF;
    IF COALESCE(instance_row.fsm_instance_status #>> '{}', 'active') <> 'active' THEN
        RETURN jsonb_build_object(
            'status', 'not_active',
            'fsm_instance_id', input_fsm_instance_id,
            'fsm_instance_status', instance_row.fsm_instance_status
        );
    END IF;

    -- 2. Stopped, with nothing left to process. A macrostep that is in flight
    --    finds this status when it takes the lock, and is discarded.
    UPDATE fsm_core.fsm_instance
    SET fsm_instance_status = '"stopped"'::jsonb,
        internal_event_queue = '[]'::jsonb,
        internal_event_count = 0,
        total_schedule_queue_data = '[]'::jsonb,
        total_async_operation_queue_data = '[]'::jsonb
    WHERE id = input_fsm_instance_id;

    -- 3. No fsmlet is given it again.
    DELETE FROM fsm_core.fsm_instance_and_fsm_workerlet
    WHERE fsm_instance_id = input_fsm_instance_id
      AND status IN ('pending', 'scheduled');
    GET DIAGNOSTICS cancelled_dispatch_count = ROW_COUNT;

    -- 4. Every message on its queue, delayed events included, is archived.
    --    Then one xstate.stop message wakes an fsmlet that is waiting on the
    --    empty queue: it sees the status and lets the instance go.
    archived_msg_ids := fsm_core.archive_fsm_instance_queue_messages_v2(input_fsm_instance_id);
    IF EXISTS (SELECT 1 FROM pgmq.list_queues() q WHERE q.queue_name = input_fsm_instance_id::text) THEN
        PERFORM pgmq.send(
            queue_name := input_fsm_instance_id::text,
            msg := jsonb_build_object(
                'eventData', jsonb_build_object(
                    'eventType', 'xstate.stop',
                    'eventPayload', '{}'::jsonb,
                    'actionType', 'stop'
                ),
                'queueId', input_fsm_instance_id,
                'queueType', instance_row.fsm_name,
                'queueVersion', instance_row.fsm_version
            )
        );
    END IF;

    -- 5. Its own invokes stop too: actors, and child machines recursively.
    FOR invoke_entry IN
        SELECT value FROM jsonb_array_elements(COALESCE(instance_row.total_async_operation_queue_data, '[]'::jsonb)) value
    LOOP
        stopped_invokes := stopped_invokes || jsonb_build_array(
            fsm_core.stop_invoked_async_operation_v2(invoke_entry)
        );
    END LOOP;

    -- 6. Log it on the instance.
    INSERT INTO fsm_core.fsm_instance_queue_event_logs (
        fsm_instance_id, fsm_instance_id_fsm_type, fsm_instance_id_fsm_version,
        event_name, event_data, event_status, execution_finished_at
    ) VALUES (
        input_fsm_instance_id, instance_row.fsm_name, instance_row.fsm_version,
        input_event_name,
        jsonb_build_object(
            'parent_fsm_instance_id', instance_row.parent_fsm_instance_id,
            'parent_invoke_id', instance_row.parent_invoke_id,
            'cancelled_dispatch_count', cancelled_dispatch_count,
            'archived_msg_ids', to_jsonb(archived_msg_ids),
            'stopped_invokes', stopped_invokes
        ),
        'stopped',
        fsm_core.tx_now()
    ) RETURNING fsm_instance_queue_event_log_id INTO event_log_id;

    RETURN jsonb_build_object(
        'status', 'stopped',
        'fsm_instance_id', input_fsm_instance_id,
        'cancelled_dispatch_count', cancelled_dispatch_count,
        'archived_msg_ids', to_jsonb(archived_msg_ids),
        'stopped_invokes', stopped_invokes,
        'event_log_id', event_log_id
    );
END;
$$;



--
-- Name: stop_invoked_async_operation_v2("jsonb"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."stop_invoked_async_operation_v2"("input_entry" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    -- Entries saved before #526 have no async_operation_type; every one of
    -- them was an actor's queue message, and was cancelled as one.
    entry_type text := COALESCE(input_entry->>'async_operation_type', 'internalAsyncOperation');
BEGIN
    IF entry_type IN ('internalAsyncOperation', 'sharedAsyncOperation') THEN
        -- Its message is cancelled, unless its result was archived first
        -- (#533). An invoke a worker is already running is stopped by the
        -- Activity Gateway, on the notification this sends (SPEC-012).
        RETURN fsm_core.finish_async_operation_event_v2(
            input_archive_reason := 'cancelled',
            input_async_operation_queue_name := input_entry->>'queue_id',
            input_async_operation_queue_msg_id := (input_entry->>'queue_msg_id')::bigint
        );
    ELSIF entry_type = 'fsm' THEN
        RETURN fsm_core.stop_child_fsm_v2((input_entry->>'queue_id')::uuid);
    ELSE
        RAISE EXCEPTION 'stop_invoked_async_operation_v2: unsupported async operation type: %', entry_type;
    END IF;
END;
$$;



--
-- Name: test_event_transition_for_entry_v1("text", "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."test_event_transition_for_entry_v1"("event_name" "text", "fsm_name_param" "text", "fsm_version_param" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    transition_record fsm_core.fsm_transitions;
    result JSONB;
BEGIN
    -- Find single record from fsm_core.fsm_transitions based on event_type, fsm_name, and fsm_version
    SELECT * INTO transition_record
    FROM fsm_core.fsm_transitions 
    WHERE event_type = event_name 
      AND fsm_name = fsm_name_param 
      AND fsm_version = fsm_version_param
    LIMIT 1;
    
    -- if event_name = "initialTransition_event" then set is_initial_transition = TRUE
    -- and call fsm_core.compute_entry_actions_v1 with is_initial_transition = TRUE
    -- else call with FALSE
    IF event_name = 'initialTransition_event' THEN
        SELECT fsm_core.compute_entry_actions_v1(transition_record := transition_record, fsm_name_param := fsm_name_param, fsm_version_param := fsm_version_param, is_initial_transition := TRUE) INTO result;
    ELSE
        SELECT fsm_core.compute_entry_actions_v1(transition_record := transition_record, fsm_name_param := fsm_name_param, fsm_version_param := fsm_version_param, is_initial_transition := FALSE) INTO result;
    END IF;


    RETURN result;
END;
$$;



--
-- Name: test_event_transition_for_entry_v2("text", "text", "text"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."test_event_transition_for_entry_v2"("event_name" "text", "fsm_name_param" "text", "fsm_version_param" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
-- For debugging: what entering on event_name's first transition does, from
-- no active states (enter_states_v2).
DECLARE
    transition_record fsm_core.fsm_transitions;
BEGIN
    SELECT * INTO transition_record
    FROM fsm_core.fsm_transitions
    WHERE event_type = event_name
      AND fsm_name = fsm_name_param
      AND fsm_version = fsm_version_param
    LIMIT 1;

    RETURN fsm_core.enter_states_v2(
        transition_record := transition_record,
        state_node_set := ARRAY[]::TEXT[],
        is_initial := event_name = 'initialTransition_event',
        fsm_name_param := fsm_name_param,
        fsm_version_param := fsm_version_param
    );
END;
$$;



--
-- Name: test_jsonb_roundtrip("jsonb"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."test_jsonb_roundtrip"("input_jsonb" "jsonb") RETURNS TABLE("original" "jsonb", "reconstructed" "jsonb", "paths" "text"[])
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    extracted_paths TEXT[];
    rebuilt_jsonb JSONB;
BEGIN
    extracted_paths := fsm_core.jsonb_all_paths(j := input_jsonb, prefix := '');
    rebuilt_jsonb := fsm_core.build_nested_json_recursive(paths := extracted_paths);
    RETURN QUERY SELECT input_jsonb, rebuilt_jsonb, extracted_paths;
END;
$$;



--
-- Name: unlock_fsm_instance("uuid"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."unlock_fsm_instance"("input_fsm_instance_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pgmq', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    updated_count INTEGER;
BEGIN
    UPDATE fsm_core.fsm_instance
    SET
        worker_locked          = FALSE,
        worker_locked_by       = NULL,
        worker_locked_at       = NULL,
        worker_lock_expires_at = NULL
    WHERE id = input_fsm_instance_id
      AND worker_locked = TRUE;

    GET DIAGNOSTICS updated_count = ROW_COUNT;
    RETURN updated_count > 0;
END;
$$;



--
-- Name: verify_api_key("bytea"); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."verify_api_key"("input_key_hash" "bytea") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'fsm_core', 'pg_temp'
    AS $$
DECLARE
  v_id   uuid;
  v_role text;
  v_last timestamptz;
BEGIN
  SELECT k.id, k.role, k.last_used_at INTO v_id, v_role, v_last
  FROM fsm_core.api_keys k
  WHERE k.key_hash = input_key_hash AND k.revoked_at IS NULL;

  IF v_id IS NULL THEN
    RETURN NULL;
  END IF;

  IF v_last IS NULL OR v_last < fsm_core.tx_now() - interval '1 minute' THEN
    UPDATE fsm_core.api_keys SET last_used_at = fsm_core.tx_now() WHERE id = v_id;
  END IF;

  RETURN v_role;
END;
$$;



