CREATE OR REPLACE FUNCTION "fsm_core"."version"() RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select '1.2.0'::text
$$;



--
-- Name: wall_now(); Type: FUNCTION; Schema: fsm_core; Owner: postgres
--

CREATE OR REPLACE FUNCTION "fsm_core"."wall_now"() RETURNS timestamp with time zone
    LANGUAGE "sql"
    AS $$
  select case
    when nullif(current_setting('fsm_core.sim_now', true), '') is null then clock_timestamp()
    when pg_has_role(session_user, 'fsm_sim', 'MEMBER')
      then current_setting('fsm_core.sim_now', true)::timestamptz
    else clock_timestamp()
  end;
$$;



