--
-- PostgreSQL database dump complete
--

-- pg_dump's header turned row_security off, which makes reading an RLS table
-- an error for a non-superuser; the cron registration reads cron.job.
SET row_security = on;

-- ── pgmq grants (from the access-control schema file) ──────────────────────
GRANT USAGE ON SCHEMA pgmq TO fsm_worker;
GRANT SELECT, UPDATE ON ALL TABLES IN SCHEMA pgmq TO fsm_worker;
ALTER DEFAULT PRIVILEGES IN SCHEMA pgmq GRANT SELECT, UPDATE ON TABLES TO fsm_worker;

-- ── The pg_cron job ─────────────────────────────────────────────────────────
SELECT fsm_core.register_scheduler_job_v2();

-- ── Installed ───────────────────────────────────────────────────────────────
DO $installed$
BEGIN
  IF fsm_core.version() <> '1.2.0' THEN
    RAISE EXCEPTION 'fsm_core.version() is %, expected 1.2.0', fsm_core.version();
  END IF;
END;
$installed$;
